return{t0=U.now(),ids=Qm,n=Rm,idsAt=U.now(),copies={},placed={},removed={},transforms={},own={},foe=setmetatable({},{__mode=cue[2504]}),foeBuffs={},meters={},steps={},deaths={},sumOf=setmetatable({},{__mode=cue[2504]}),summons={},casts={},castN={},sales=0,firstPlaced={},nearN=0}
end
function pb.tick()
local Sm=bb.pas
if not Sm then
Sm=pb.newWatch()
bb.pas=Sm
end
if U.now()-Sm.idsAt>30 then
Sm.ids,Sm.n=pb.watchIds()
Sm.idsAt=U.now()
end
if(Sm.n or 0)==0 then
return
end
if not Sm.planned then
local Tm,Um=pcall(pb.plan,Sm)
if not Tm then
Sm.planned=true
F.log(1,cue[2505],cue[2506]..tostring(Um))
end
end
local Vm=U.now()-Sm.t0
local Wm={}
local Xm={}
for Ym,Zm in ipairs(bb.mine or{})do
local _m=Zm:FindFirstChild(cue[2182])
local an=_m and _m:FindFirstChild(cue[2496])
if an then
local bn=an.Value
Wm[Zm]=true
local cn=Sm.copies[Zm]
local dn=_m:FindFirstChild(cue[2210])
local en=dn and tonumber(dn.Value)or 0
if not cn then
cn={id=bn,at=Vm,lvl=en,sold=Sm.sales,buff={},stat={}}
Sm.copies[Zm]=cn
if#Sm.placed<200 then
table.insert(Sm.placed,{t=Vm,id=bn,sold=Sm.sales})
end
if Sm.firstPlaced[bn]==nil then
Sm.firstPlaced[bn]=Vm
end
local gn=bb.pasExp
if type(gn)==cue[2118]and gn.kind==cue[2301]and bn~=gn.id and Sm.sales>0 and not V.isFarm(bn)then
gn.otherDone=true
end
end
if cn.id~=bn then
if#Sm.transforms<20 then
table.insert(Sm.transforms,{t=Vm,from=cn.id,to=bn})
end
cn.id=bn
end
cn.lvl=math.max(cn.lvl,en)
local hn=_m:FindFirstChild(cue[2507])
cn.max=hn and tonumber(hn.Value)or cn.max
local jn=Zm:FindFirstChild(cue[2508])
for kn,ln in ipairs(jn and jn:GetChildren()or{})do
local mn=(ln:IsA(cue[2509])and tonumber(ln.Value))or 1
local nn=ln.Name
cn.buff[nn]=math.max(cn.buff[nn]or-math.huge,mn)
if mn>0 then
local pn=Sm.own[nn]
if not pn then
pn={first=Vm,last=Vm,max=mn,by={},vals={},starts={}}
Sm.own[nn]=pn
end
pn.last,pn.max=Vm,math.max(pn.max,mn)
pn.by[bn]=(pn.by[bn]or 0)+1
Xm[nn]=(Xm[nn]or 0)+1
if#pn.vals<12 then
local qn=math.floor(mn*1000+0.5)/1000
local rn=false
for un,vn in ipairs(pn.vals)do
if vn==qn then
rn=true
break
end
end
if not rn then
table.insert(pn.vals,qn)
end
end
end
end
if Sm.ids[bn]then
local wn=_m:FindFirstChild(cue[2510])
cn.tk=wn and tonumber(wn.Value)or cn.tk
local xn=_m:FindFirstChild(cue[2371])
cn.range=xn and tonumber(xn.Value)or cn.range
local yn,zn=pcall(function()
return Zm:GetPivot().Position
end)
if yn then
cn.pos=zn
end
local An=0
for Bn,Cn in ipairs(_m:GetChildren())do
if Cn:IsA(cue[2511])or Cn:IsA(cue[2512])then
local Dn=Cn.Name
if not pb.STAT_SKIP[Dn]then
local En=tonumber(Cn.Value)
local Fn=cn.stat[Dn]
if En and(Fn or An<24)then
if not Fn then
Fn={lo=En,hi=En}
cn.stat[Dn]=Fn
An=An+1
end
Fn.lo,Fn.hi=math.min(Fn.lo,En),math.max(Fn.hi,En)
end
end
end
end
end
end
end
for Gn,Hn in pairs(Xm)do
local In=Sm.own[Gn]
if In and(Sm.ownCnt and(Sm.ownCnt[Gn]or 0)or 0)==0 and#In.starts<40 then
table.insert(In.starts,Vm)
end
end
Sm.ownCnt=Xm
for Jn,Kn in pairs(Sm.copies)do
if not Wm[Jn]and not Kn.gone then
Kn.gone=Vm
local Ln=Kn.max~=nil and Kn.lvl>=Kn.max
if#Sm.removed<100 then
table.insert(Sm.removed,{t=Vm,id=Kn.id,lvl=Kn.lvl,atMax=Ln or nil})
end
if Ln and Sm.ids[Kn.id]then
Sm.sales=Sm.sales+1
Sm.lastSale=Vm
end
end
end
local Mn=bb.pasExp
if type(Mn)==cue[2118]and Mn.kind==cue[2301]and not Mn.otherDone and not Mn.freed and bb.reinc and(bb.reinc.sold or 0)>0 and U.now()-(tonumber(bb.reinc.soldAt)or 0)>20 then
local Nn,On=pcall(pb.freeSlot,Mn)
if not Nn then
Mn.freed=true
F.log(1,cue[2505],cue[2513]..tostring(On))
end
end
local Pn={}
for Qn,Rn in pairs(Sm.copies)do
if not Rn.gone and Sm.ids[Rn.id]and Rn.pos and Rn.range then
table.insert(Pn,Rn)
end
end
local Sn,Tn={},0
for Un,Vn in ipairs(bb.enemies or{})do
local Wn=Vn.m
if Wn and Vn.pos then
Sn[Wn]=true
local Xn=false
local Yn=U.flat(Vn.pos)
for Zn,ao in ipairs(Pn)do
if(Yn-U.flat(ao.pos)).Magnitude<=ao.range+3 then
Xn=true
break
end
end
local bo=Sm.foe[Wn]
if Xn or bo then
local co=Wn:FindFirstChildOfClass(cue[2514])
local eo=math.max(1,(co and co.MaxHealth)or Vn.hp or 1)
if not bo then
bo={hp=Vn.hp,on={},met={},speed0=co and co.WalkSpeed or nil,boss=Vn.boss or nil}
Sm.foe[Wn]=bo
Sm.nearN=Sm.nearN+1
end
Tn=Tn+1
if Tn<=pb.ENEMY_MAX then
local fo=Wn:FindFirstChild(cue[2182])
local ho={}
for io,jo in ipairs(fo and fo:GetChildren()or{})do
if jo.Name:sub(1,8)==cue[2515]and jo:IsA(cue[2509])and tonumber(jo.Value)then
ho[jo.Name]=tonumber(jo.Value)/eo
end
end
local ko=((bo.hp or Vn.hp)-Vn.hp)/eo
if ko>=0.08 and#Sm.steps<300 then
local mo
for oo,po in pairs(bo.met)do
if po>0.02 and(ho[oo]or 0)<po*0.3 then
mo=mo or{}
mo[oo]=po
end
end
table.insert(Sm.steps,{t=Vm,before=(bo.hp or Vn.hp)/eo,drop=ko,boss=Vn.boss or nil,reset=mo})
end
for qo,ro in pairs(ho)do
local so=Sm.meters[qo]or{max=0,n=0}
so.max,so.n=math.max(so.max,ro),so.n+1
Sm.meters[qo]=so
end
bo.met=ho
local uo=Wn:FindFirstChild(cue[2508])
local vo={}
for wo,xo in ipairs(uo and uo:GetChildren()or{})do
local yo=(xo:IsA(cue[2509])and tonumber(xo.Value))or 1
if yo~=0 then
vo[xo.Name]=yo
end
end
for zo,Ao in pairs(vo)do
local Bo=Sm.foeBuffs[zo]
if not Bo then
Bo={first=Vm,last=Vm,n=0,foes=0,near=0,boss=0,max=Ao,durs={},sp=0,spN=0,onsets={}}
Sm.foeBuffs[zo]=Bo
end
Bo.n,Bo.last,Bo.max=Bo.n+1,Vm,math.max(Bo.max,Ao)
if Xn then
Bo.near=Bo.near+1
end
if bo.boss then
Bo.boss=Bo.boss+1
end
if not bo.on[zo]then
bo.on[zo]=Vm
Bo.foes=Bo.foes+1
if#Bo.onsets<200 then
table.insert(Bo.onsets,Vm)
end
end
if co and(bo.speed0 or 0)>0 then
Bo.sp,Bo.spN=Bo.sp+co.WalkSpeed/bo.speed0,Bo.spN+1
end
end
for Co,Do in pairs(bo.on)do
if not vo[Co]then
local Eo=Sm.foeBuffs[Co]
if Eo and#Eo.durs<80 then
table.insert(Eo.durs,Vm-Do)
end
bo.on[Co]=nil
end
end
end
bo.hp=Vn.hp
bo.frac=(Vn.hp or 0)/eo
end
end
end
for Fo,Go in pairs(Sm.foe)do
if not Sn[Fo]then
if#Sm.deaths<600 and Go.frac then
table.insert(Sm.deaths,{frac=Go.frac,boss=Go.boss})
end
Sm.foe[Fo]=nil
end
end
for Ho,Io in pairs(bb.helperDealt or{})do
if Io.owner and Sm.ids[Io.owner]then
local Jo=Sm.sumOf[Ho]
if not Jo then
local Ko=0
for Lo,Mo in pairs(Sm.copies)do
if Mo.id==Io.owner and not Mo.gone then
Ko=Ko+(Mo.tk or 0)
end
end
Jo={owner=Io.owner,id=Io.id,born=Vm,tk=Ko}
Sm.sumOf[Ho]=Jo
if#Sm.summons<200 then
table.insert(Sm.summons,Jo)
end
end
if Ho.Parent then
Jo.last=Vm
elseif not Jo.died then
Jo.died=Vm
end
end
end
for No in pairs(Sm.ids)do
local Oo=bb.casts and tonumber(bb.casts[No])or 0
if Oo>(Sm.castN[No]or 0)then
Sm.castN[No]=Oo
if#Sm.casts<100 then
table.insert(Sm.casts,{t=Vm,id=No})
end
end
end
end
function pb.evidence(Po,Qo,Ro)
local So=type(Ro.nums)==cue[2118]and Ro.nums or{}
local To=Po.firstPlaced[Qo]
if not To then
return{why=cue[2516]}
end
local Uo={}
for Vo,Wo in ipairs(Ro.buffs or{})do
Uo[Wo]=true
end
local function Xo(Yo)
if#Yo==0 then
return nil
end
table.sort(Yo)
return Yo[math.ceil(#Yo/2)]
end
if Ro.family==cue[2301]then
if(Po.sales or 0)==0 then
return{why=cue[2517]}
end
local Zo,_o
for ap in pairs(Po.own)do
local bp,cp,dp,ep,fp=0,0,0,0,0
for ip,jp in pairs(Po.copies)do
local kp=jp.buff[ap]or 0
if(jp.sold or 0)>0 then
if jp.id~=Qo then
ep=ep+1
end
if kp>0 then
if jp.id==Qo then
bp=bp+1
else
dp=dp+1
end
fp=math.max(fp,kp)
end
elseif kp>0 then
cp=cp+1
end
end
if bp>0 and cp==0 and(not _o or bp>_o)then
Zo,_o={name=ap,other=dp,otherAfter=ep,top=fp},bp
end
end
if not Zo then
return{why=cue[2518]}
end
local lp=(Zo.other>0 and cue[1048])or(Zo.otherAfter>0 and cue[2519])or cue[2520]
return{seen=true,buff=Zo.name,who=lp,nums={stacks=(Po.sales>1 and Zo.top>1)or nil,sales=Po.sales},why=string.format(cue[2521],_o,Zo.name,lp==cue[2519]and cue[2522]or cue[1037])}
end
local mp=Ro.trigger and tostring(Ro.trigger):find(cue[2523],1,true)~=nil
local np=0
for op,pp in ipairs(Po.casts)do
if pp.id==Qo then
np=np+1
end
end
if mp and np==0 and(Ro.family==cue[2302]or Ro.family==cue[2299])then
return{why=cue[2524]}
end
if Ro.family==cue[2302]then
local qp,rp,vp
for wp,yp in pairs(Po.own)do
if yp.first>=To-1 and(Uo[wp]or yp.first<=To+5 or mp)and(not mp or pb.nearCast(Po,Qo,yp.starts)>0)then
local zp=0
for Ap,Bp in pairs(yp.by)do
if Ap~=Qo then
zp=zp+Bp
end
end
if zp>0 and(not qp or(Uo[wp]and not vp)or((Uo[wp]or false)==(vp or false)and zp>rp))then
qp,rp,vp=wp,zp,Uo[wp]
end
end
end
if not qp then
return{why=cue[2525]}
end
return{seen=true,buff=qp,why=string.format(cue[2526],qp)}
end
if Ro.family==cue[2299]then
local Cp,Dp
for Ep,Fp in pairs(Po.foeBuffs)do
if Fp.first>=To-1 and Fp.near>0 and(Uo[Ep]or Fp.near>=0.5*Fp.n)and(not mp or pb.nearCast(Po,Qo,Fp.onsets)>0)then
local Gp=Fp.near+(Uo[Ep]and 1e6 or 0)+(mp and pb.nearCast(Po,Qo,Fp.onsets)*1000 or 0)
if not Dp or Gp>Dp then
Cp,Dp=Ep,Gp
end
end
end
if not Cp then
return{why=cue[2527]}
end
local Hp=Po.foeBuffs[Cp]
local Ip={}
if#Hp.durs>=3 then
Ip.secsSeen=math.floor(Xo(Hp.durs)*10+0.5)/10
elseif Hp.foes>=5 then
Ip.keepSeen=true
end
if Hp.spN>=5 then
local Jp=Hp.sp/Hp.spN
if Jp<0.97 then
Ip.slowSeen=math.floor((1-Jp)*100+0.5)/100
end
end
if So.chance and(Po.nearN or 0)>0 then
Ip.chanceSeen=math.floor(math.min(1,Hp.foes/Po.nearN)*100+0.5)/100
end
Ip.bossToo=Hp.boss>0 or nil
return{seen=true,buff=Cp,nums=Ip,why=string.format(cue[2528],Hp.foes,Cp)}
end
if Ro.family==cue[2357]then
local Kp=(tonumber(So.below)or 0.25)+0.02
local Lp,Mp=0,0
for Np,Op in ipairs(Po.deaths)do
if not Op.boss then
Mp=Mp+1
if Op.frac>0.04 and Op.frac<=Kp then
Lp=Lp+1
end
end
end
if Mp<10 then
return{why=cue[2529]}
end
local Pp=Lp/Mp
if Pp<0.3 then
return{why=string.format(cue[2530],math.floor(Pp*100))}
end
return{seen=true,nums={shareSeen=math.floor(Pp*100+0.5)/100},why=string.format(cue[2531],Lp,Mp,math.floor(Kp*100))}
end
if Ro.family==cue[2205]then
local Qp={}
for Rp,Sp in ipairs(Po.summons)do
if Sp.owner==Qo then
table.insert(Qp,Sp)
end
end
if#Qp<2 then
return{why=cue[2532]}
end
table.sort(Qp,function(Tp,Vp)
return Tp.born<Vp.born
end)
local Wp,Xp,Yp={},{},{}
for Zp=2,#Qp do
local _p=(Qp[Zp].tk or 0)-(Qp[Zp-1].tk or 0)
if _p>0 then
table.insert(Wp,_p)
end
end
for aq,bq in ipairs(Qp)do
if bq.died then
table.insert(Xp,bq.died-bq.born)
end
table.insert(Yp,{bq.born,1})
table.insert(Yp,{bq.died or bq.last or bq.born,-1})
end
table.sort(Yp,function(cq,dq)
return cq[1]<dq[1]
end)
local eq,fq=0,0
for gq,hq in ipairs(Yp)do
eq=eq+hq[2]
fq=math.max(fq,eq)
end
local iq=Xo(Xp)
return{seen=true,nums={everySeen=Xo(Wp),lifeSeen=iq and math.floor(iq+0.5)or nil,capSeen=fq,made= #Qp},why=string.format(cue[2533],#Qp)}
end
if Ro.family==cue[2303]then
local jq,kq
for lq,mq in pairs(Po.own)do
if(mq.by[Qo]or 0)>0 and mq.first>=To-1 and(not jq or(Uo[lq]and not Uo[jq]))then
jq,kq=lq,mq
end
end
local nq
for oq,pq in ipairs(Po.transforms)do
if pq.from==Qo then
nq=pq.to
end
end
if not jq then
local qq,rq,sq
for tq,uq in pairs(Po.copies)do
if uq.id==Qo or(nq and uq.id==nq)then
for vq,wq in pairs(uq.stat or{})do
if wq.hi>wq.lo and(not qq or(wq.hi-wq.lo)>(sq-rq))then
qq,rq,sq=vq,wq.lo,wq.hi
end
end
end
end
if not qq then
return{why=cue[2534]}
end
return{seen=true,nums={stat=qq,loSeen=rq,hiSeen=sq,transformTo=nq},why=string.format(cue[2535],qq,tostring(rq),tostring(sq))}
end
return{seen=true,buff=jq,nums={maxSeen=kq.max,steps= #kq.vals,transformTo=nq},why=string.format(cue[2536],jq,tostring(kq.max))}
end
if Ro.family==cue[2300]then
local xq,yq,zq={},{},nil
for Aq,Bq in ipairs(Po.steps)do
for Cq,Dq in pairs(Bq.reset or{})do
table.insert(xq,Dq)
table.insert(yq,Bq.drop)
zq=zq or Cq
end
end
if#xq<3 then
return{why=cue[2537]}
end
return{seen=true,nums={atSeen=Xo(xq),hitSeen=Xo(yq),meter=zq},why=string.format(cue[2538],#xq)}
end
if Ro.family==cue[2269]then
return{why=cue[2539]}
end
return{why=cue[2540]}
end
function pb.learn(Eq)
local Fq={}
for Gq in pairs(Eq.ids or{})do
local Hq,Iq=pcall(pb.guess,Gq)
for Jq,Kq in ipairs(Hq and type(Iq)==cue[2118]and Iq or{})do
if Kq.playable and not Kq.hand then
local Lq,Mq=pcall(pb.evidence,Eq,Gq,Kq)
if Lq and type(Mq)==cue[2118]and Mq.seen then
local Nq=type(P.pasBook[Gq])==cue[2118]and P.pasBook[Gq]or{}
local Oq=type(Nq[Kq.pid])==cue[2118]and Nq[Kq.pid]or nil
local Pq={}
for Qq,Rq in pairs(Kq.nums or{})do
Pq[Qq]=Rq
end
for Sq,Tq in pairs(Mq.nums or{})do
Pq[Sq]=Tq
end
local Uq=Oq~=nil and Oq.family==Kq.family and(Oq.buff==nil or Mq.buff==nil or Oq.buff==Mq.buff)
Nq[Kq.pid]={family=Kq.family,name=Kq.name,nums=Pq,buff=Mq.buff or(Oq and Oq.buff),who=Mq.who or Kq.who,trigger=Kq.trigger,keyword=Kq.keyword,sure=(Uq and(tonumber(Oq.runs)or 0)>=1)and cue[2481]or cue[2541],runs=(Uq and(tonumber(Oq.runs)or 0)or 0)+1,at=os.time(),why=Mq.why}
P.pasBook[Gq]=Nq
table.insert(Fq,{id=Gq,g=Kq,e=Nq[Kq.pid]})
elseif Lq and type(Mq)==cue[2118]then
table.insert(Fq,{id=Gq,g=Kq,miss=Mq.why})
else
table.insert(Fq,{id=Gq,g=Kq,miss=cue[2542]..tostring(Mq)})
end
end
end
end
pb._model={}
return Fq
end
function pb.unexplained(Vq,Wq)
if not(Vq and Vq.firstPlaced and Vq.firstPlaced[Wq])then
return nil
end
local Xq={}
for Yq,Zq in ipairs(Vq.learned or{})do
if Zq.id==Wq and Zq.e and Zq.e.buff then
Xq[Zq.e.buff]=true
end
end
local _q={}
for ar,br in pairs(Vq.own)do
if(br.by[Wq]or 0)>0 and not Xq[ar]then
table.insert(_q,{w=cue[2543],b=ar,n=br.by[Wq],max=br.max})
end
end
for cr,dr in pairs(Vq.foeBuffs)do
if dr.near>0 and dr.first>=Vq.firstPlaced[Wq]-1 and not Xq[cr]then
table.insert(_q,{w=cue[2544],b=cr,n=dr.foes,max=dr.max})
end
end
table.sort(_q,function(er,gr)
return er.n>gr.n
end)
local hr={}
for ir=1,math.min(6,#_q)do
hr[ir]=_q[ir]
end
return#hr>0 and hr or nil
end
function pb.finish()
local jr=bb.pas
if not(jr and(jr.n or 0)>0)then
return
end
local kr=pb.learn(jr)
jr.learned=kr
local lr=P.trial and P.trial.study
if lr and bb.trialId then
P.pasBook[bb.trialId]=type(P.pasBook[bb.trialId])==cue[2118]and P.pasBook[bb.trialId]or{}
P.pasBook[bb.trialId]._tries=(tonumber(P.pasBook[bb.trialId]._tries)or 0)+1
end
for mr,nr in ipairs(kr)do
if nr.e then
F.log(1,cue[2492],string.format(cue[2545],V.name(nr.id),nr.g.name,pb.words(pb.withBook(nr.id,nr.g)),pb.SURE_WORDS[nr.e.sure]or tostring(nr.e.sure),tostring(nr.e.why)))
elseif lr and nr.id==bb.trialId then
F.log(1,cue[2492],string.format(cue[2546],V.name(nr.id),nr.g.name,tostring(nr.miss)))
end
end
F.saveSoon()
end
function pb.reportOf(pr)
local qr=type(P.pasBook)==cue[2118]and type(P.pasBook[pr])==cue[2118]and P.pasBook[pr]or nil
if not qr then
return nil
end
local rr={}
for sr,ur in pairs(qr)do
if type(ur)==cue[2118]then
table.insert(rr,{p=sr,name=ur.name,f=ur.family,s=ur.sure,b=ur.buff,w=ur.who,k=ur.keyword,t=ur.trigger,n=ur.nums,y=ur.why and tostring(ur.why):sub(1,120)or nil,r=ur.runs})
end
end
table.sort(rr,function(vr,wr)
return tostring(vr.p)<tostring(wr.p)
end)
return#rr>0 and rr or nil
end
function pb.rules(xr)
local yr=type(P.pasBook)==cue[2118]and type(P.pasBook[xr])==cue[2118]and P.pasBook[xr]or nil
local zr,Ar=pcall(db.hivePassive,xr)
local Br={}
for Cr,Dr in pairs(yr or{})do
if type(Dr)==cue[2118]and(Dr.sure==cue[2541]or Dr.sure==cue[2481])then
Br[Cr]=Dr
end
end
for Er,Fr in pairs(zr and type(Ar)==cue[2118]and Ar or{})do
if Br[Er]==nil and type(Fr)==cue[2118]and(Fr.sure==cue[2541]or Fr.sure==cue[2481])then
Br[Er]=Fr
end
end
return Br
end
function pb.sellAdd(Gr)
for Hr,Ir in pairs(pb.rules(Gr))do
if Ir.family==cue[2301]and Ir.who~=cue[1048]then
local Jr=tonumber(type(Ir.nums)==cue[2118]and Ir.nums.add)
if Jr and Jr>0 then
return Jr
end
end
