function kb.xpGuess(scb)
local tcb=scb.level and N.Levels[scb.level]
if not tcb then
return 0
end
local ucb=math.min(9,tonumber(tcb.story_world_rank)or tonumber(scb.rank)or 9)
local vcb=tonumber(tcb.story_level_rank)or 6
local wcb=(scb.kind==cue[2159]and 1.5 or 1)*(ucb>5 and 2 or 1)
local xcb=2.1564^(ucb-1)*(40+10*vcb)/wcb
if scb.kind==cue[2138]then
xcb=3*30*2.1564^(ucb-1)/wcb
end
local ycb=ucb>=9 and 0.3 or(ucb>=7 and 0.5 or 1)
return xcb*ycb*6
end
function kb.modeBonus(zcb)
