local Wcb=Vcb.xp*Pcb
local Xcb=math.min(Vcb.n,math.floor((Qcb-Scb)/math.max(1,Wcb)))
if Xcb>0 then
Rcb[Vcb.id]=Xcb
Scb=Scb+Xcb*Wcb
