function eb.upgradeGain(dDb,eDb,fDb,gDb,hDb,iDb)
local jDb,kDb=eDb[fDb],eDb[fDb+1]
local lDb=(jDb.cd>0 and jDb.damage/jDb.cd or 0)
local mDb=(kDb.cd>0 and kDb.damage/kDb.cd or 0)*V.aoe(kDb.atk,kDb.range)/math.max(0.3,V.aoe(jDb.atk,jDb.range))
local nDb=lDb>0 and dDb*(mDb/lDb-1)or(iDb or 0)
local oDb=eDb[fDb+2]
if oDb and fDb+1<eDb.max and oDb.cd>0 and kDb.cd>0 and lDb>0 then
local pDb=dDb*((oDb.damage/oDb.cd)/lDb-1)
local qDb=gDb+oDb.cost*hDb
if pDb/qDb>nDb/gDb then
nDb=nDb+(pDb/qDb*gDb-nDb)*0.5
end
end
local rDb=(kDb.range or 0)>(jDb.range or 0)and(1+((kDb.range-jDb.range)/math.max(1,jDb.range)))or 1
return math.max(0,nDb)*rDb
end
function eb.dpsFor(sDb,tDb)
if tDb<=0 then
return 0
