table.insert(uDb,wDb)
end
end
table.sort(uDb,function(xDb,yDb)
return xDb.gain/xDb.cost>yDb.gain/yDb.cost
end)
local zDb,ADb=0,0
for BDb,CDb in ipairs(uDb)do
if tDb<=0 then
break
end
ADb=CDb.gain/CDb.cost
local DDb=math.min(1,tDb/CDb.cost)
zDb=zDb+CDb.gain*DDb
tDb=tDb-CDb.cost*DDb
end
return zDb+math.max(0,tDb)*ADb*0.7
end
function eb.shieldDps(EDb,FDb,GDb,HDb,IDb,JDb,KDb)
if(HDb or 0)<=0 or(EDb or 0)<=0 or(IDb or 0)<=0 then
