if xic[jb.T.SHOP]then
if yic>=10 and yic<=15 then
zic=zic+(wic>=300 and 5 or 1)
else
zic=zic+(wic>=300 and(yic>15 and 3 or 1)or 0.3)
end
end
if xic[jb.T.SHRINE]then
zic=zic+1.5
end
