elseif Sic.type==cue[4021]and Sic.stat==cue[2371]then
Mic.range=Mic.range+Tic
elseif Sic.type==cue[4022]and tostring(Sic.stat):sub(1,9)==cue[4033]then
local Uic=tostring(Sic.stat):sub(10)
