elseif Sic.type==cue[4026]and Sic.stat==cue[4027]then
Mic.crit=Mic.crit+Tic
elseif Sic.type==cue[4030]then
Mic.cost=Mic.cost+Tic
elseif Sic.type==cue[4034]and Sic.stat==cue[3615]then
Mic.hp=Mic.hp+Tic
elseif Sic.type==cue[4029]then
Mic.speed=Mic.speed+Tic
elseif Sic.type==cue[4035]then
Mic.regen=Mic.regen+Tic
elseif Sic.type==cue[4036]then
Mic.shield=Mic.shield+Tic
elseif Sic.type==cue[4037]and Sic.passive==cue[4038]then
Mic.fly=Mic.fly+Tic
elseif Sic.type==cue[4037]and Sic.passive==cue[4039]then
Mic.burst=(Mic.burst or 0)+Tic
end
end
end
Mic.cd,Mic.cost,Mic.speed=math.max(0.1,Mic.cd),math.max(0.1,Mic.cost),math.max(0.1,Mic.speed)
