function jb.sim(bjc,cjc,djc)
if not O.sim or type(bjc.r._l)~=cue[2118]then
return nil
end
local ejc=tostring(bjc.r._r or(bjc.d..cue[2254]..bjc.choice))..(cjc and(cue[2433]..tostring(cjc))or cue[1037])..(djc and cue[4047]or cue[1037])
local fjc=jb.data()
local gjc=jb.fx(fjc,jb.roomCurse(bjc.r),cjc)
local hjc=W.teamSig()..cue[2552]..jb.fxText(gjc)..(O.killZone~=false and cue[4048]or cue[1037])..(bb.forcedWay()and(cue[2552]..bb.forcedWay())or cue[1037])
local ijc=P.dg.sim[ejc]
if ijc and ijc.sig==hjc then
return not ijc.none and ijc or nil
end
local jjc={}
for kjc,ljc in ipairs(V.equipped())do
table.insert(jjc,ljc.u)
end
if#jjc==0 then
return nil
end
local mjc=gb.applyFx(gb.info(gb.slim(bjc.r._l),cue[2843],nil,jb.mod(bjc.r._l)),gjc)
jb.applyK(mjc,bjc.r._r)
if djc then
mjc.zone=false
end
local njc=gb.wave(mjc,1,true)
if#njc==0 then
ijc={none=true,sig=hjc,at=os.time()}
else
local ojc=gb.evaluate(mjc,gb.teamFrom(jjc,mjc.map))
ijc={p=ojc.p,wave=ojc.wave,won=ojc.won,total=mjc.total,margin=ojc.margin,sig=hjc,at=os.time(),zone=mjc.zone~=false or nil}
end
P.dg.sim[ejc]=ijc
if U.count(P.dg.sim)>60 then
local pjc,qjc
for rjc,sjc in pairs(P.dg.sim)do
if not qjc or(sjc.at or 0)<qjc then
pjc,qjc=rjc,sjc.at or 0
end
end
P.dg.sim[pjc]=nil
end
F.saveSoon()
return not ijc.none and ijc or nil
end
function jb.winP(tjc)
local ujc=tostring(math.min(4,math.max(1,math.ceil(tjc.d/5))))
local vjc=P.dg.depth[ujc]or{runs=0,wins=0}
local wjc=U.clamp(0.95-0.015*tjc.d,0.5,0.95)
local xjc=((tonumber(vjc.wins)or 0)+wjc*2)/((tonumber(vjc.runs)or 0)+2)
local yjc,zjc=pcall(jb.sim,tjc)
if yjc and zjc and zjc.p then
local Ajc,Bjc=pcall(gb.styleP,zjc,zjc.zone==false and cue[3891]or(zjc.zone and cue[3827]or nil))
xjc=(xjc*2+(Ajc and Bjc or zjc.p))/3
end
return xjc,yjc and zjc or nil
end
function jb.hopeless(Cjc)
return Cjc~=nil and Cjc.won==false and(tonumber(Cjc.p)or 1)<=0.05
