function jb.blindCurse(Kjc,Ljc)
return jb.fxText(jb.fx(Kjc,Ljc))==jb.fxText(jb.fx(Kjc))
end
function jb.curseOk(Mjc,Njc,Ojc,Pjc,Qjc)
local Rjc=tostring((jb.item(Mjc)or{}).name or Mjc)
local Sjc,Tjc,Ujc=jb.curseBar(Njc,Ojc)
if Sjc>0.2 and jb.blindCurse(Njc,Mjc)then
return false,string.format(cue[4052],Rjc,Ujc)
end
local function Vjc(Wjc)
return Wjc==nil or(tonumber(Wjc.p)or 1)>=Sjc
end
if Pjc then
local Xjc,Yjc=pcall(jb.sim,Pjc,nil,true)
if Xjc and not Vjc(Yjc)then
return false,string.format(cue[4053],Rjc,(Tjc:gsub(cue[3690],cue[4054])),tostring(Yjc.margin or cue[2354]))
end
end
if#Qjc==0 then
return true
end
local Zjc
for _jc,akc in ipairs(Qjc)do
local bkc,ckc=pcall(jb.sim,akc,Mjc,true)
if not bkc or Vjc(ckc)then
return true
end
if not Zjc or(tonumber(ckc.p)or 0)>(tonumber(Zjc.p)or 0)then
Zjc=ckc
end
end
return false,string.format(cue[4055],Rjc,Tjc,tostring(Zjc and Zjc.margin or cue[2354]))
end
function jb.curseGate(dkc,ekc)
