end
function jb.payValue()
local gkc,hkc=0,0
for ikc,jkc in ipairs(P.dg.pay or{})do
if type(jkc.items)==cue[2118]then
local kkc=tonumber(jkc.gems)or 0
for lkc,mkc in pairs(jkc.items)do
if(tonumber(mkc)or 0)>0 then
kkc=kkc+W.itemValue(lkc,mkc)
end
end
gkc,hkc=gkc+kkc,hkc+1
end
end
if hkc<5 then
return nil
end
return gkc/hkc*0.7
end
jb.LOSS_PRIOR={won=3,n=12}
function jb.lossWin()
local nkc=type(P.dg)==cue[2118]and type(P.dg.lossCalls)==cue[2118]and P.dg.lossCalls or{}
return U.clamp(((tonumber(nkc.won)or 0)+jb.LOSS_PRIOR.won)/((tonumber(nkc.n)or 0)+jb.LOSS_PRIOR.n),0.05,0.95)
