function jb.pick(okc)
local pkc,qkc=jb.curses(okc),jb.lives(okc)
local rkc=jb.res(okc)
local skc=jb.rooms(okc)
local tkc={}
for ukc,vkc in ipairs(skc)do
table.insert(tkc,tostring(vkc.r._r))
end
local wkc=table.concat(tkc,cue[2986])..string.format(cue[4056],qkc,rkc,pkc,W.teamSig())
if jb._pick and jb._pick.sig==wkc then
return jb._pick.x
end
local xkc,ykc,zkc,Akc
for Bkc,Ckc in ipairs(skc)do
local Dkc=jb.roomValue(Ckc,rkc)
local Ekc,Fkc
for Gkc,Hkc in ipairs(jb.after(okc,Ckc.choice))do
local Ikc=jb.roomValue(Hkc,rkc)
if not Ekc or Ikc>Ekc then
Ekc,Fkc=Ikc,Hkc
end
end
local Jkc,Kkc=jb.winP(Ckc)
local Lkc=Kkc~=nil and Kkc.won==false
local Mkc=qkc>=3 and 1 or(qkc==2 and 2 or 6)
local Nkc=1-(1-Jkc)^math.max(1,qkc)
Ckc.oldScore=Nkc*(Dkc+0.6*(Ekc or 0))-(1-Jkc)*Mkc
if Lkc then
Jkc=math.min(Jkc,jb.lossWin())
Nkc=Jkc
Mkc=Mkc*2
end
Ckc.p,Ckc.sim,Ckc.value,Ckc.nextValue,Ckc.nextRoom,Ckc.simLost=Jkc,Kkc,Dkc,Ekc or 0,Fkc,Lkc or nil
Ckc.score=Nkc*(Dkc+0.6*(Ekc or 0))-(1-Jkc)*Mkc
local Okc,Pkc,Qkc=pcall(jb.curseGate,Ckc,okc)
if Okc and not Pkc then
Ckc.blocked=Qkc
end
if not Ckc.blocked then
if not xkc or Ckc.score>xkc.score then
xkc=Ckc
end
if Lkc then
if not Akc or Ckc.score>Akc.score then
Akc=Ckc
end
elseif not zkc or Ckc.score>zkc.score then
zkc=Ckc
end
end
if not ykc or Ckc.score>ykc.score then
ykc=Ckc
end
end
if xkc and xkc.simLost and zkc then
F.log(1,cue[4057],string.format(cue[4058],jb.roomName(xkc),tostring(xkc.sim and xkc.sim.margin or cue[2354]),math.floor((1-jb.lossWin())*100+0.5),jb.roomName(zkc)))
elseif xkc and Akc and Akc~=xkc and Akc.oldScore>xkc.score then
F.log(1,cue[4057],string.format(cue[4059],jb.roomName(Akc),tostring(Akc.sim and Akc.sim.margin or cue[2354]),jb.roomName(xkc)))
end
xkc=xkc or ykc
jb._pick={sig=wkc,x=xkc,rooms=skc}
return xkc
end
