vlc=tonumber(tlc)
end
if type(ulc)==cue[1023]and jb.item(ulc)then
table.insert(rlc,{key=slc,id=ulc,cost=vlc or tonumber(jb.item(ulc).cost)or 0,bought=type(tlc)==cue[2118]and(tlc.bought or tlc.sold or tlc.purchased)or nil})
end
