function jb.buy(ylc)
local zlc=jb.res(jb.data())
local Alc={}
if P.dg.buyArg==cue[2496]then
Alc={ylc.id,ylc.key}
else
Alc={ylc.key,ylc.id}
end
if Alc[1]==Alc[2]then
Alc[2]=nil
end
for Blc,Clc in ipairs(Alc)do
local Dlc,Elc=F.request(cue[4067],cue[4068],Clc)
local Flc=U.now()
while U.now()-Flc<3 and jb.res(jb.data())>=zlc do
task.wait(0.25)
end
if jb.res(jb.data())<zlc then
P.dg.buyArg=(Clc==ylc.id and ylc.id~=ylc.key)and cue[2496]or cue[4069]
return true
end
if not Dlc then
