jb.LUCK_RESERVE=500
jb.MIN_WORTH=0.02
jb.TOP_WORTH=0.08
function jb.shop(Llc,Mlc)
local Nlc=jb.cleared(Llc)
local Olc=jb.res(Llc)
local Plc=1+0.1*(jb.items(Llc)._curse_shop or 0)
local Qlc=jb.shopAhead(Llc)and math.ceil(jb.LUCK_RESERVE*Plc)or 0
local Rlc={}
local Slc,Tlc={},0
for Ulc,Vlc in ipairs(jb.offers(Mlc and Mlc.data))do
Vlc.cost=math.ceil(Vlc.cost*Plc)
table.insert(Slc,tostring(jb.item(Vlc.id).name or Vlc.id))
if not Vlc.bought and not jb.isCurse(Vlc.id)then
Vlc.luck=tonumber(jb.item(Vlc.id).luck_increase)~=nil
Vlc.v=jb.itemValue(Vlc.id,Llc)
if not Vlc.luck and Vlc.v/math.max(1,Vlc.cost)<jb.MIN_WORTH then
Tlc=Tlc+1
elseif Vlc.v>0 and(Vlc.luck or Nlc>=10 or Vlc.v/math.max(1,Vlc.cost)>=jb.TOP_WORTH)then
table.insert(Rlc,Vlc)
end
end
end
table.sort(Rlc,function(Wlc,Xlc)
if Wlc.luck~=Xlc.luck then
return Wlc.luck
end
return Wlc.v/math.max(1,Wlc.cost)>Xlc.v/math.max(1,Xlc.cost)
end)
local Ylc,Zlc,_lc={},0,0
for amc,bmc in ipairs(Rlc)do
if bmc.cost<=Olc-(bmc.luck and 0 or Qlc)then
if jb.buy(bmc)then
Olc=jb.res(jb.data())
table.insert(Ylc,string.format(cue[4070],tostring(jb.item(bmc.id).name or bmc.id),bmc.cost))
end
elseif bmc.cost<=Olc then
_lc=_lc+1
else
Zlc=Zlc+1
