local Erc=zrc:Lerp(Arc,Drc/Crc)
table.insert(bb.samples,{pos=Erc,prog=(xrc+Brc*Drc/Crc)/math.max(1,vrc),lane=prc.Name})
end
xrc=xrc+Brc
end
if rrc[#rrc]then
