function bb.readHidden(Hrc)
local Irc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(Irc)~=cue[2118]or not next(Irc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
