end
local Jrc
for Krc,Lrc in pairs(Hrc)do
if Irc[Krc.Name]and type(Lrc.points)==cue[2118]and#Lrc.points>=2 then
local Mrc={}
for Nrc,Orc in ipairs(Lrc.points)do
Mrc[Nrc]=U.flat(Orc.part.Position)
end
local Prc={}
for Qrc,Rrc in ipairs(bb.samples)do
local Src=tostring(Rrc.lane)
Prc[Src]=Prc[Src]or{}
table.insert(Prc[Src],Rrc)
end
local Trc,Urc
for Vrc,Wrc in pairs(Prc)do
local Xrc=0
for Yrc=1,#Mrc,math.max(1,math.floor(#Mrc/20))do
local Zrc=math.huge
for _rc,asc in ipairs(Wrc)do
local bsc=(U.flat(asc.pos)-Mrc[Yrc]).Magnitude
if bsc<Zrc then
Zrc=bsc
end
end
Xrc=Xrc+Zrc
end
if not Urc or Xrc<Urc then
Trc,Urc=Vrc,Xrc
end
end
local csc,dsc,esc,fsc,gsc,hsc={},nil,nil,nil,0,0
