local osc=(U.flat(nsc.pos)-jsc).Magnitude
if osc<lsc then
lsc,ksc=osc,nsc.prog
end
end
hsc=math.max(hsc,lsc)
if esc then
local psc=ksc-esc
local qsc=(psc>0.002 and 1)or(psc< -0.002 and-1)or fsc
if fsc and qsc and qsc~=fsc then
table.insert(csc,math.floor(esc*1000+0.5)/1000)
