task.wait()
end
end
if esc and hsc<=8 then
table.insert(csc,math.floor(esc*1000+0.5)/1000)
Jrc=Jrc or{}
Jrc[Krc.Name]={from=math.floor((dsc or 0)*1000+0.5)/1000,len=math.floor(gsc*1000+0.5)/1000,turns=csc,road=Trc}
