local hwc=gwc._stats
if not V.isFarm(hwc.id.Value)and hwc:FindFirstChild(cue[2371])then
table.insert(ewc,{p=U.flat(gwc:GetPivot().Position),r=hwc.range.Value*(V.SUMMONER[hwc.id.Value]and V.SUMMONER[hwc.id.Value].reach or 1),air=bb.canAir(gwc)})
end
