local iwc,jwc=0,0
if#ewc>0 then
for kwc,lwc in ipairs(bb.samples)do
if lwc.prog>jwc then
local mwc=U.flat(lwc.pos)
for nwc,owc in ipairs(ewc)do
if(mwc-owc.p).Magnitude<=owc.r then
if lwc.prog>iwc then
iwc=lwc.prog
end
if owc.air then
jwc=lwc.prog
break
end
end
end
end
end
end
local pwc,qwc={},bb.laneCount
if qwc and qwc.n>=2 and#ewc>0 then
local rwc={}
for swc,twc in ipairs(bb.samples)do
local uwc=U.flat(twc.pos)
for vwc,wwc in ipairs(ewc)do
if(uwc-wwc.p).Magnitude<=wwc.r then
local xwc=tostring(twc.lane)
rwc[xwc]=(rwc[xwc]or 0)+1
if twc.prog>(pwc[xwc]or 0)then
pwc[xwc]=twc.prog
end
break
end
end
end
local ywc,zwc={},0
for Awc,Bwc in pairs(qwc.by)do
ywc[Awc]=(rwc[Awc]or 0)/math.max(1,Bwc)
zwc=math.max(zwc,ywc[Awc])
