bb.laneW={}
for Cwc,Dwc in pairs(qwc.by)do
bb.laneW[Cwc]=(qwc.avg/math.max(1,Dwc))*(1+1.5*(zwc>0 and(1-ywc[Cwc]/zwc)or 0))
end
bb.laneFrac=ywc
