if#ewc>0 then
for Hwc,Iwc in ipairs(dwc)do
local Jwc=(bb.laneW and Iwc.lane)and(pwc[tostring(Iwc.lane)]or 0)or iwc
if Iwc.hp>0 and Iwc.prog>Jwc+0.02 and Iwc.prog>(Ewc or 0)then
Ewc,Gwc=Iwc.prog,bb.laneW and Iwc.lane or nil
end
if Iwc.hp>0 and Iwc.fly and Iwc.prog>jwc+0.02 then
Fwc=true
end
end
end
local Kwc= #ewc>0 and(bb.pressure or 0)>=iwc-0.08
return{covEnd=iwc,airEnd=jwc,leak=Ewc,leakLane=Gwc,covL=pwc,airLeak=Fwc,push=Kwc,units= #ewc}
end
