if O.mapStudy~=false and not O.lowLag and not XGc and not SGc and not RGc and not bb.fastAlways then
local nLc={info=MDc,team=tFc,key=bb.bookKey(MDc),base=TGc,hard=lLc,scale=NDc,attackers={}}
for oLc,pLc in ipairs(PDc)do
