bb.STUDY_K,bb.STUDY_BEAM,bb.BOOK_MAX,bb.STUDY_SHARED=12,3,40,8
function bb.bookKey(sLc)
return tostring(sLc and sLc.key)..cue[2553]..tostring(sLc and sLc.map)
end
function bb.bookFor(tLc)
