return type(uLc)==cue[2118]and type(uLc.spots)==cue[2118]and uLc or nil
end
function bb.hiveSpots(vLc)
local wLc=db.hive()
local xLc=wLc and type(wLc.mapSpots)==cue[2118]and wLc.mapSpots[tostring(vLc)]or nil
return type(xLc)==cue[2118]and xLc or{}
end
function bb.hiveUnitSpots(yLc,zLc)
local ALc=db.hive()
local BLc=ALc and type(ALc.unitSpots)==cue[2118]and ALc.unitSpots[tostring(yLc)]or nil
local CLc=type(BLc)==cue[2118]and BLc[tostring(zLc)]or nil
if type(CLc)~=cue[2118]or type(CLc.spots)~=cue[2118]then
return{},nil
end
return CLc.spots,tonumber(CLc.base)
end
function bb.nearSpot(DLc,ELc,FLc)
local GLc,HLc=nil,9
for ILc,JLc in ipairs(DLc or{})do
local KLc=(JLc.X-ELc)^2+(JLc.Z-FLc)^2
if KLc<=HLc then
GLc,HLc=JLc,KLc
end
end
return GLc
end
function bb.baseRange(LLc)
local MLc=V.rows(LLc)
local NLc=MLc and MLc[MLc.max]and tonumber(MLc[MLc.max].range)
return NLc or(N.Units[LLc]and tonumber(N.Units[LLc].range))or nil
end
function bb.studyMoves(OLc,PLc)
local QLc=V.rows(OLc.id)
local RLc=V.range(OLc.e.u,QLc.max)*PLc
local SLc=RLc*RLc
local TLc,ULc={},{}
local VLc,WLc=bb.hurtSamples(),bb.sandLine()
for XLc,YLc in ipairs(OLc.spots or{})do
local ZLc,_Lc,aMc,bMc,cMc=0,0,0,0,0
for dMc,eMc in ipairs(VLc)do
local fMc,gMc=eMc.pos.X-YLc.X,eMc.pos.Z-YLc.Z
if fMc*fMc+gMc*gMc<=SLc then
aMc=aMc+1
local hMc=math.min(49,math.floor(eMc.prog*50))
if hMc<25 then
ZLc=bit32 .bor(ZLc,bit32 .lshift(1,hMc))
else
_Lc=bit32 .bor(_Lc,bit32 .lshift(1,hMc-25))
end
if eMc.prog-WLc<=0.3 then
bMc=bMc+1
elseif eMc.prog>=0.7 then
cMc=cMc+1
end
end
end
if aMc>0 then
local iMc=ZLc..cue[2254].._Lc
local jMc=TLc[iMc]
if not jMc then
jMc={p=YLc,lo=ZLc,hi=_Lc,n=aMc,early=bMc,late=cMc}
TLc[iMc]=jMc
table.insert(ULc,jMc)
elseif aMc>jMc.n then
jMc.p,jMc.n,jMc.early,jMc.late=YLc,aMc,bMc,cMc
end
end
if XLc%40==0 then
task.wait()
end
end
local kMc={}
for lMc,mMc in ipairs(ULc)do
local nMc=false
for oMc,pMc in ipairs(ULc)do
if lMc~=oMc and pMc.n>=mMc.n and bit32 .band(mMc.lo,pMc.lo)==mMc.lo and bit32 .band(mMc.hi,pMc.hi)==mMc.hi and(pMc.lo~=mMc.lo or pMc.hi~=mMc.hi or pMc.n>mMc.n)then
nMc=true
break
end
end
if not nMc then
table.insert(kMc,mMc)
end
if lMc%40==0 then
task.wait()
end
end
local qMc,rMc={},{}
local function sMc(tMc)
if tMc and not rMc[tMc]then
rMc[tMc]=true
table.insert(qMc,tMc)
end
end
table.sort(kMc,function(uMc,vMc)
return uMc.n>vMc.n
end)
for wMc=1,math.min(bb.STUDY_K,#kMc)do
sMc(kMc[wMc].p)
end
table.sort(kMc,function(xMc,yMc)
return xMc.early>yMc.early
end)
sMc(kMc[1]and kMc[1].p)
sMc(kMc[2]and kMc[2].p)
table.sort(kMc,function(zMc,AMc)
return zMc.late>AMc.late
end)
sMc(kMc[1]and kMc[1].p)
sMc(kMc[2]and kMc[2].p)
local BMc=0
for CMc,DMc in ipairs((bb.hiveUnitSpots(bb.ld and bb.ld.map,OLc.id)))do
local EMc=tonumber(DMc.x)and tonumber(DMc.z)and bb.nearSpot(OLc.spots,tonumber(DMc.x),tonumber(DMc.z))or nil
if EMc and not rMc[EMc]then
sMc(EMc)
BMc=BMc+1
end
end
for FMc,GMc in ipairs(bb.hiveSpots(bb.ld and bb.ld.map))do
if BMc>=bb.STUDY_SHARED then
break
end
local HMc=false
for IMc,JMc in ipairs(type(GMc.units)==cue[2118]and GMc.units or{})do
local KMc=JMc==OLc.id and RLc or((bb.baseRange(JMc)or 0)*PLc)
if JMc==OLc.id or(KMc>0 and math.abs(KMc-RLc)<=0.3*RLc)then
HMc=true
break
end
end
local LMc=HMc and tonumber(GMc.x)and tonumber(GMc.z)and bb.nearSpot(OLc.spots,tonumber(GMc.x),tonumber(GMc.z))or nil
if LMc and not rMc[LMc]then
sMc(LMc)
BMc=BMc+1
end
end
return qMc,#ULc,#kMc,BMc
end
function bb.studyRun(MMc)
local NMc=U.now()
while F.alive and not(bb.finished or bb.result)and(bb.planning or U.now()-NMc<20)do
task.wait(1)
end
local function OMc()
return F.alive and not(bb.finished or bb.result)and O.mapStudy~=false and not O.lowLag and F.where==cue[2191]
end
if not OMc()then
return
end
local PMc,QMc,RMc=MMc.info,MMc.team,MMc.base
local SMc=PMc.timeLimit~=nil
local TMc=SMc and 1 or math.max(1,tonumber(MMc.hard)or 1)
local UMc={TMc*0.95,TMc*1.05}
local VMc=bb.bookFor(PMc)
local WMc={key=MMc.key,label=bb.label(),n=VMc and tonumber(VMc.n)or 0,run=0,timed=SMc,kills=PMc.killScore and true or nil,hp=TMc,at=os.time()}
bb.study=WMc
local XMc,YMc,ZMc,_Mc,aNc={},0,0,0,0
for bNc,cNc in ipairs(MMc.attackers)do
local dNc,eNc,fNc,gNc=bb.studyMoves(cNc,MMc.scale)
XMc[cNc.id]=dNc
YMc,ZMc,_Mc,aNc=YMc+ #(cNc.spots or{}),ZMc+eNc,_Mc+ #dNc,aNc+gNc
if not OMc()then
return
end
end
WMc.moves=_Mc
F.log(1,cue[2877],string.format(cue[4377],WMc.label,YMc,ZMc,_Mc,aNc>0 and string.format(cue[4378],aNc)or cue[1037]))
local hNc={}
local function iNc(jNc)
return{samples=bb.samples,cache=hNc,spots=jNc,style=RMc.style,list=RMc.list,hybridHill=RMc.hybridHill}
end
local function kNc(lNc)
local mNc=0
for nNc,oNc in pairs(lNc)do
local pNc=bb.spotRec(nNc,oNc)
if pNc then
mNc=mNc+(tonumber(pNc.wins)or 0)*200-((tonumber(pNc.runs)or 0)-(tonumber(pNc.wins)or 0))*1500
end
end
return mNc
end
local function qNc(rNc)
local sNc,tNc,uNc=0,0,0
for vNc,wNc in ipairs(UMc)do
local xNc=os.clock()
local yNc=gb.runRaw(PMc,QMc,{hpMul=wNc,layout=iNc(rNc),bg=true})
sNc,tNc,uNc=sNc+gb.objective(yNc),tNc+(tonumber(yNc.kills)or 0),uNc+(tonumber(yNc.wave)or 0)
task.wait(math.clamp((os.clock()-xNc)*3,0.25,MMc.pauseMax or 1.5))
if not OMc()then
return nil
end
end
WMc.n,WMc.run=WMc.n+1,WMc.run+1
return sNc/ #UMc*100+kNc(rNc),tNc/ #UMc,uNc/ #UMc
end
local function zNc(ANc)
local BNc={}
for CNc,DNc in pairs(ANc)do
BNc[CNc]=DNc
end
return BNc
end
local function ENc(FNc,GNc,HNc)
for INc,JNc in pairs(FNc)do
if INc~=GNc and(U.flat(JNc)-U.flat(HNc)).Magnitude<4.5 then
return true
end
end
return false
end
local KNc={spots=zNc(RMc.spots)}
KNc.s,KNc.kills,KNc.wave=qNc(KNc.spots)
if not KNc.s then
return bb.studyEnd(WMc,MMc,nil)
end
WMc.baseKills,WMc.baseWave=KNc.kills,KNc.wave
WMc.bestKills,WMc.bestWave=KNc.kills,KNc.wave
if VMc and VMc.aside==nil then
local LNc,MNc=zNc(KNc.spots),0
for NNc,ONc in ipairs(MMc.attackers)do
local PNc=VMc.spots[ONc.id]
local QNc=type(PNc)==cue[2118]and tonumber(PNc[1])and tonumber(PNc[3])and bb.nearSpot(ONc.spots,tonumber(PNc[1]),tonumber(PNc[3]))or nil
if QNc and QNc~=LNc[ONc.id]and not ENc(LNc,ONc.id,QNc)then
LNc[ONc.id]=QNc
MNc=MNc+1
end
end
if MNc>0 then
local RNc,SNc,TNc=qNc(LNc)
if not RNc then
return bb.studyEnd(WMc,MMc,KNc)
end
if RNc>KNc.s then
KNc={spots=LNc,s=RNc,kills=SNc,wave=TNc}
WMc.bestKills,WMc.bestWave=SNc,TNc
end
end
end
local UNc,VNc=U.now(),WMc.run
local function WNc(XNc)
if not(XNc.s and XNc.s>KNc.s+math.max(50,math.abs(KNc.s)*0.005))then
return false
end
KNc=XNc
WMc.bestKills,WMc.bestWave,WMc.better=XNc.kills,XNc.wave,(WMc.better or 0)+1
pcall(bb.bookSave,PMc,MMc,KNc,WMc)
return true
end
local function YNc()
if WMc.run-VNc>=60 or U.now()-UNc>240 then
UNc,VNc=U.now(),WMc.run
F.log(1,cue[2877],bb.studyWords(WMc))
end
end
local ZNc={KNc}
for _Nc,aOc in ipairs(MMc.attackers)do
local bOc={}
for cOc,dOc in ipairs(ZNc)do
table.insert(bOc,dOc)
for eOc,fOc in ipairs(XMc[aOc.id]or{})do
if fOc~=dOc.spots[aOc.id]and not ENc(dOc.spots,aOc.id,fOc)then
local gOc=zNc(dOc.spots)
gOc[aOc.id]=fOc
local hOc,iOc,jOc=qNc(gOc)
if not hOc then
return bb.studyEnd(WMc,MMc,KNc)
end
local kOc={spots=gOc,s=hOc,kills=iOc,wave=jOc}
table.insert(bOc,kOc)
WNc(kOc)
YNc()
end
end
end
table.sort(bOc,function(lOc,mOc)
return(lOc.s or-1e18)>(mOc.s or-1e18)
end)
ZNc={}
for nOc=1,math.min(bb.STUDY_BEAM,#bOc)do
table.insert(ZNc,bOc[nOc])
end
end
local oOc={}
for pOc,qOc in ipairs(MMc.attackers)do
if XMc[qOc.id]and#XMc[qOc.id]>0 then
table.insert(oOc,qOc.id)
end
end
while OMc()and#oOc>0 do
local rOc=zNc(KNc.spots)
for sOc=1,math.min(2,#oOc)do
local tOc=oOc[math.random(#oOc)]
local uOc=XMc[tOc]
local vOc=uOc[math.random(#uOc)]
if not ENc(rOc,tOc,vOc)then
rOc[tOc]=vOc
end
end
local wOc,xOc,yOc=qNc(rOc)
if not wOc then
break
end
WNc({spots=rOc,s=wOc,kills=xOc,wave=yOc})
YNc()
end
bb.studyEnd(WMc,MMc,KNc)
end
bb.STUDY_INF_WAIT=240
function bb.validOpen(zOc,AOc)
local BOc=N.PC.raycast(zOc+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not BOc then
return nil
end
if not N.PC.is_valid_raycast_hit(BOc.Instance,AOc)then
return nil
end
local COc=BOc.Position
if bb.blockedSpot(COc)then
return nil
end
local DOc=(tonumber(AOc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(DOc*2,2.5,DOc*2)
bb.probe.CFrame=CFrame.new(COc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
return COc
end
function bb.studyInfinite()
if O.mapStudy==false or O.lowLag or not(bb.info and bb.infinite)or bb.kind==cue[2574]then
return
end
local EOc=bb.info
local function FOc()
return not F.alive or bb.finished or bb.result or F.where~=cue[2191]or O.mapStudy==false or bb.withOthers or bb.fastAlways
end
local GOc,HOc={},{}
for IOc,JOc in ipairs(bb.team or{})do
table.insert(GOc,JOc.u)
if not V.isFarm(JOc.id)and not V.allyBuff(JOc.id)and JOc.uuid~=bb.trainee and V.rows(JOc.id)then
local KOc,LOc=pcall(V.score,JOc.u,bb.mod)
table.insert(HOc,{e=JOc,id=JOc.id,sc=KOc and LOc or 0})
end
end
if#HOc==0 then
return
end
table.sort(HOc,function(MOc,NOc)
return MOc.sc>NOc.sc
end)
local function OOc()
local POc,QOc={},0
for ROc,SOc in ipairs(HOc)do
for TOc,UOc in ipairs(bb.mine or{})do
local VOc=UOc:FindFirstChild(cue[2182])
local WOc=VOc and VOc:FindFirstChild(cue[2495])
if WOc and WOc.Value==SOc.e.uuid and VOc:FindFirstChild(cue[2496])and VOc.id.Value==SOc.id then
POc[SOc.id]=UOc:GetPivot().Position
QOc=QOc+1
break
end
end
end
return POc,QOc
end
local XOc=U.now()
local YOc,ZOc=OOc()
while ZOc< #HOc and U.now()-XOc<bb.STUDY_INF_WAIT do
task.wait(5)
if FOc()then
return
end
YOc,ZOc=OOc()
end
if ZOc==0 or FOc()then
return
end
local _Oc={}
local function aPc(bPc)
local cPc=bPc.hybrid_placement and not bPc.hill_unit
local dPc=cPc and bb.hybridHill
local ePc=((bPc.hill_unit or dPc)and cue[2903]or(cPc and cue[4305])or cue[4306])..cue[2254]..tostring(bPc.override_hitbox_radius or cue[1037])
if _Oc[ePc]then
return _Oc[ePc]
end
local fPc={}
local gPc=dPc and bb.hillData(bPc)or bPc
for hPc,iPc in ipairs(bb.cands or{})do
local jPc=bb.validOpen(iPc,gPc)
if jPc then
table.insert(fPc,jPc)
end
if hPc%40==0 then
task.wait()
end
end
_Oc[ePc]=fPc
return fPc
end
local kPc={info=EOc,team=gb.teamFrom(GOc,EOc.map),key=bb.bookKey(EOc),hard=1,scale=tonumber(EOc.rangeScale)or 1,attackers={},pauseMax=4,inf=true}
local lPc={spots={},style=cue[3064],hybridHill=bb.hybridHill and true or false}
for mPc,nPc in ipairs(HOc)do
local oPc=(gb.holds(nPc.id)and not V.killFed(nPc.id))and true or false
local pPc=oPc and{}or table.clone(aPc(nPc.e.data))
if FOc()then
return
end
local qPc=YOc[nPc.id]
if qPc then
local rPc=bb.nearSpot(pPc,qPc.X,qPc.Z)
if not rPc then
rPc=qPc
table.insert(pPc,qPc)
end
lPc.spots[nPc.id]=rPc
end
if#pPc>0 then
table.insert(kPc.attackers,{id=nPc.id,e=nPc.e,spots=pPc})
end
end
kPc.base=lPc
bb.studyPool=kPc
F.log(1,cue[2877],string.format(cue[4379],bb.label(),ZOc))
bb.studyRun(kPc)
