end
return string.format(cue[4381],tostring(sPc.label),tonumber(sPc.n)or 0,tonumber(sPc.run)or 0,tPc(sPc.bestKills,sPc.bestWave),tPc(sPc.baseKills,sPc.baseWave),(sPc.better or 0)>0 and cue[4382]or cue[1037])
