function bb.bookSave(wPc,xPc,yPc,zPc)
P.mapBook=type(P.mapBook)==cue[2118]and P.mapBook or{}
local APc={}
for BPc,CPc in pairs(yPc.spots or{})do
APc[BPc]={math.floor(CPc.X*10+0.5)/10,math.floor(CPc.Y*10+0.5)/10,math.floor(CPc.Z*10+0.5)/10}
end
P.mapBook[xPc.key]={spots=APc,style=xPc.base.style,hp=zPc.hp,n=zPc.n,kills=yPc.kills and math.floor(yPc.kills+0.5)or nil,wave=yPc.wave and math.floor(yPc.wave*10+0.5)/10 or nil,base=zPc.baseWave and math.floor(zPc.baseWave*10+0.5)/10 or nil,label=zPc.label,map=wPc.map,killScore=zPc.kills,at=os.time()}
local DPc={}
for EPc,FPc in pairs(P.mapBook)do
table.insert(DPc,{k=EPc,at=type(FPc)==cue[2118]and tonumber(FPc.at)or 0})
end
if#DPc>bb.BOOK_MAX then
table.sort(DPc,function(GPc,HPc)
return GPc.at>HPc.at
end)
for IPc=bb.BOOK_MAX+1,#DPc do
P.mapBook[DPc[IPc].k]=nil
end
end
F.saveSoon()
end
function bb.studyEnd(JPc,KPc,LPc)
if type(JPc)~=cue[2118]or JPc.ended then
return
end
JPc.ended=true
if LPc and KPc then
local MPc=bb.bookFor(KPc.info)
if MPc then
MPc.n=JPc.n
F.saveSoon()
elseif JPc.run>0 then
pcall(bb.bookSave,KPc.info,KPc,LPc,JPc)
end
end
if JPc.run>0 then
F.log(1,cue[2877],bb.studyWords(JPc))
end
end
function bb.studyReport()
