if not NPc then
return nil
end
local OPc={}
for PPc,QPc in pairs(NPc.spots)do
if type(QPc)==cue[2118]then
OPc[PPc]={QPc[1],QPc[3]}
end
end
return{n=NPc.n,kills=NPc.kills,wave=NPc.wave,hp=NPc.hp,spots=OPc}
