end
return string.format(cue[4385],RPc,tostring(SPc.label),tonumber(SPc.n)or 0,SPc.killScore and string.format(cue[4317],tonumber(SPc.kills)or 0)or string.format(cue[4386],tostring(SPc.wave)))
