bb.LAYOUT_KEEP,bb.LAYOUT_CONTROL,bb.HIVE_ASIDE,bb.HIVE_LEAD,bb.HIVE_LEAD_MIN=8,2,3600,0.015,300
bb.HIVE_TRY_EVERY,bb.HIVE_TRIALS=3,3
function bb.layoutRecFor(eQc,fQc)
local gQc=bb.bookKey(eQc)
P.layoutRec=type(P.layoutRec)==cue[2118]and P.layoutRec or{}
local hQc=P.layoutRec[gQc]
if type(hQc)~=cue[2118]then
if not fQc then
return nil
end
hQc={at=os.time()}
P.layoutRec[gQc]=hQc
if U.count(P.layoutRec)>80 then
local iQc,jQc
for kQc,lQc in pairs(P.layoutRec)do
local mQc=type(lQc)==cue[2118]and tonumber(lQc.at)or 0
if not jQc or mQc<jQc then
iQc,jQc=kQc,mQc
end
end
P.layoutRec[iQc]=nil
end
end
return hQc
end
function bb.layoutAdd(nQc,oQc,pQc,qQc,rQc)
nQc.runs,nQc.wins=(tonumber(nQc.runs)or 0)+1,(tonumber(nQc.wins)or 0)+(oQc and 1 or 0)
nQc.sec,nQc.wave=type(nQc.sec)==cue[2118]and nQc.sec or{},type(nQc.wave)==cue[2118]and nQc.wave or{}
if oQc and tonumber(pQc)then
table.insert(nQc.sec,math.floor(pQc+0.5))
end
table.insert(nQc.wave,tonumber(qQc)or 0)
if tonumber(rQc)then
nQc.kills=type(nQc.kills)==cue[2118]and nQc.kills or{}
table.insert(nQc.kills,math.floor(tonumber(rQc)))
while#nQc.kills>bb.LAYOUT_KEEP do
table.remove(nQc.kills,1)
end
end
while#nQc.sec>bb.LAYOUT_KEEP do
table.remove(nQc.sec,1)
end
while#nQc.wave>bb.LAYOUT_KEEP do
table.remove(nQc.wave,1)
end
end
function bb.layoutJudge(sQc,tQc,uQc,vQc,wQc)
wQc=wQc or cue[4388]
local xQc,yQc=tonumber(sQc and sQc.runs)or 0,tonumber(tQc and tQc.runs)or 0
if xQc<1 or yQc<bb.LAYOUT_CONTROL then
return nil
end
if vQc and type(sQc.kills)==cue[2118]and type(tQc.kills)==cue[2118]and#sQc.kills>=1 and#tQc.kills>=bb.LAYOUT_CONTROL then
local zQc,AQc=bb.labMedian(sQc.kills),bb.labMedian(tQc.kills)
if zQc and AQc and zQc<AQc*0.97 and(#sQc.kills>=2 or zQc<AQc*0.85)then
return string.format(cue[4389],zQc,AQc,wQc)
end
return nil
end
local BQc,CQc=(tonumber(sQc.wins)or 0)/xQc,(tonumber(tQc.wins)or 0)/yQc
if not uQc and CQc>=0.5 then
if BQc+0.25<CQc and(xQc>=2 or(BQc==0 and CQc>=0.9 and yQc>=3))then
return string.format(cue[4390],tonumber(sQc.wins)or 0,xQc,xQc==1 and cue[1037]or cue[1964],tonumber(tQc.wins)or 0,yQc,wQc)
end
local DQc,EQc=bb.labMedian(sQc.sec),bb.labMedian(tQc.sec)
if DQc and EQc and DQc>EQc*1.10 and(#sQc.sec>=2 or DQc>EQc*1.25)then
return string.format(cue[4391],math.floor(DQc/60),DQc%60,math.floor(EQc/60),EQc%60,wQc)
end
return nil
end
local FQc,GQc=bb.labMedian(sQc.wave),bb.labMedian(tQc.wave)
if FQc and GQc and FQc<GQc-math.max(1,GQc*0.03)and(xQc>=2 or FQc<GQc*0.85)then
return string.format(cue[4392],FQc,GQc,wQc)
end
return nil
end
function bb.layoutResult(HQc,IQc)
local JQc=bb.info
local KQc=bb.layoutSrc
if not(JQc and KQc)or bb.labTest or bb.withOthers or bb.fastAlways then
return
end
if bb.infinite and not JQc.timeLimit then
return
end
local LQc=bb.wave()
local MQc=bb.layoutRecFor(JQc,true)
MQc.at=os.time()
local NQc=JQc.timeLimit~=nil
local OQc=JQc.killScore and true or nil
local PQc=OQc and(bb.killsEnd or bb.realKills())or nil
if KQc==cue[4358]then
local QQc=bb.bookFor(JQc)
if not QQc then
return
end
QQc.real=type(QQc.real)==cue[2118]and QQc.real or{}
bb.layoutAdd(QQc.real,HQc,IQc,LQc,PQc)
local RQc=QQc.aside==nil and bb.layoutJudge(QQc.real,MQc.own,NQc,OQc)or nil
if RQc then
QQc.aside={at=os.time(),why=RQc}
F.log(1,cue[4293],string.format(cue[4393],RQc))
end
elseif KQc==cue[3726]then
MQc.hiveUnit=type(MQc.hiveUnit)==cue[2118]and MQc.hiveUnit or{}
local SQc=MQc.hiveUnit
bb.layoutAdd(SQc,HQc,IQc,LQc,PQc)
local TQc=bb.bookFor(JQc)
local UQc=TQc and type(TQc.real)==cue[2118]and(tonumber(TQc.real.runs)or 0)>=bb.LAYOUT_CONTROL
local VQc=UQc and TQc.real or MQc.own
local WQc=bb.layoutJudge(SQc,VQc,NQc,OQc,UQc and cue[4394]or nil)
if WQc then
SQc.aside,SQc.why=os.time(),WQc
F.log(1,cue[4293],string.format(cue[4395],WQc))
elseif(tonumber(SQc.runs)or 0)>=bb.HIVE_TRIALS then
local XQc=VQc and bb.layoutJudge(VQc,SQc,NQc,OQc,cue[4396])
if XQc and TQc and type(bb.hiveUnitPlan)==cue[2118]then
for YQc,ZQc in pairs(bb.hiveUnitPlan)do
TQc.spots[YQc]=ZQc
end
TQc.real={runs=SQc.runs,wins=SQc.wins,sec=SQc.sec,wave=SQc.wave,kills=SQc.kills}
TQc.hive,TQc.aside=os.time(),nil
MQc.hiveUnit=nil
F.log(1,cue[4293],string.format(cue[4397],XQc))
else
SQc.aside,SQc.why=os.time(),cue[4398]
F.log(1,cue[4293],cue[4399])
end
end
else
MQc[KQc]=type(MQc[KQc])==cue[2118]and MQc[KQc]or{}
local _Qc=MQc[KQc]
bb.layoutAdd(_Qc,HQc,IQc,LQc,PQc)
if KQc==cue[3725]and _Qc.aside==nil then
local aRc=bb.layoutJudge(_Qc,MQc.own,NQc,OQc)
if aRc then
_Qc.aside,_Qc.why=os.time(),aRc
F.log(1,cue[4293],string.format(cue[4400],aRc))
end
end
end
F.saveSoon()
end
bb.CONTROL_WORDS={cue[4401],cue[4402],cue[4403],cue[4404]}
function bb.controlSpot(bRc,cRc)
if not bb.killZone()then
return nil
end
local dRc=gb.holds
if not dRc(bRc.id)or V.toggleOf(bRc.id)then
return nil
end
local eRc,fRc,gRc,hRc=1,0,0,{}
local iRc=bb.hurtSamples()
for jRc,kRc in ipairs(bb.mine or{})do
local lRc=kRc._stats
local mRc=lRc.id.Value
if lRc:FindFirstChild(cue[2371])and not V.isFarm(mRc)and not V.allyBuff(mRc)then
local nRc,oRc=U.flat(kRc:GetPivot().Position),lRc.range.Value
if dRc(mRc)and not V.toggleOf(mRc)then
gRc=gRc+1
table.insert(hRc,{p=nRc,r=oRc})
else
for pRc,qRc in ipairs(iRc)do
if(U.flat(qRc.pos)-nRc).Magnitude<=oRc then
eRc,fRc=math.min(eRc,qRc.prog),math.max(fRc,qRc.prog)
end
end
end
end
end
if fRc<=eRc then
eRc,fRc=0.75,0.98
end
local rRc=(cRc or gRc)+1
local sRc=({eRc,fRc,(eRc+fRc)/2,eRc-(fRc-eRc)/2})[rRc]
if not sRc then
return nil
end
local tRc=V.range(bRc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local uRc={}
for vRc,wRc in ipairs(bb.cands)do
local xRc,yRc,zRc=U.flat(wRc),0,0
for ARc,BRc in ipairs(iRc)do
if(U.flat(BRc.pos)-xRc).Magnitude<=tRc then
zRc=zRc+1
if math.abs(BRc.prog-sRc)<=0.05 then
yRc=yRc+1
local CRc=U.flat(BRc.pos)
for DRc,ERc in ipairs(hRc)do
if(CRc-ERc.p).Magnitude<=ERc.r then
yRc=yRc-0.5
break
end
end
end
end
end
if yRc>0 then
table.insert(uRc,{pos=wRc,sc=yRc,cov=zRc})
end
if vRc%60==0 then
task.wait()
end
end
table.sort(uRc,function(FRc,GRc)
return FRc.sc>GRc.sc
end)
for HRc,IRc in ipairs(uRc)do
local JRc=bb.valid(IRc.pos,bRc.data)
if JRc then
F.log(1,cue[4232],string.format(cue[4405],V.name(bRc.id),bb.CONTROL_WORDS[rRc],math.floor(sRc*100+0.5)))
return JRc,IRc.cov,sRc
end
if HRc%20==0 then
task.wait()
end
end
return nil
end
function bb.holdSpot(KRc)
local LRc,MRc=gb.holds(KRc.id)
if not LRc then
return nil
end
if V.killFed(KRc.id)then
return nil
end
local NRc,ORc={},0
for PRc,QRc in ipairs(bb.mine or{})do
local RRc=QRc._stats
local SRc=RRc.id.Value
if RRc:FindFirstChild(cue[2371])and not V.isFarm(SRc)and not V.allyBuff(SRc)and SRc~=KRc.id then
local TRc,URc=pcall(bb.liveDps,QRc,SRc)
URc=TRc and tonumber(URc)or 0
if URc>0 then
table.insert(NRc,{p=U.flat(QRc:GetPivot().Position),r=RRc.range.Value,d=URc})
ORc=ORc+URc
end
end
end
if#NRc==0 or ORc<=0 then
return nil
end
local VRc=bb.hurtSamples()
local WRc={}
for XRc,YRc in ipairs(VRc)do
local ZRc,_Rc=U.flat(YRc.pos),0
for aSc,bSc in ipairs(NRc)do
if(ZRc-bSc.p).Magnitude<=bSc.r then
_Rc=_Rc+bSc.d
end
end
WRc[XRc]=_Rc/ORc
end
local cSc=V.range(KRc.u,math.min(tonumber(MRc)or 0,3,V.rows(KRc.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1)
local dSc,eSc,fSc
for gSc,hSc in ipairs(bb.cands)do
local iSc,jSc,kSc=U.flat(hSc),0,0
for lSc,mSc in ipairs(VRc)do
if(U.flat(mSc.pos)-iSc).Magnitude<=cSc then
jSc=jSc+WRc[lSc]
kSc=kSc+1
end
end
if jSc>0 and(not eSc or jSc>eSc)then
local nSc=bb.valid(hSc,KRc.data)
if nSc then
dSc,eSc,fSc=nSc,jSc,kSc
end
end
if gSc%40==0 then
task.wait()
end
end
if not dSc then
return nil
end
bb.holdSaid=bb.holdSaid or{}
if not bb.holdSaid[KRc.id]then
bb.holdSaid[KRc.id]=true
F.log(1,cue[4232],string.format(cue[4406],V.name(KRc.id)))
end
return dSc,fSc or 0
end
function bb.bestSpot(oSc,pSc,qSc)
if(oSc._grif or oSc.id==V.GRIF.egg)and not qSc and bb.grifOn()then
local rSc,sSc,tSc=pcall(bb.grifSpot,oSc)
if rSc and sSc then
return sSc,tSc
end
if not rSc and ab.every(cue[4407],30)then
F.log(1,cue[2505],cue[4408]..tostring(sSc))
end
if oSc._grif then
return nil,0
end
end
if bb.hybridHill and not oSc._hillTry and type(oSc.data)==cue[2118]and oSc.data.hybrid_placement and not oSc.data.hill_unit then
local uSc=setmetatable({data=bb.hillData(oSc.data),_hillTry=true},{__index=oSc})
local vSc,wSc,xSc=pcall(bb.bestSpot,uSc,pSc,qSc)
if vSc and wSc then
return wSc,xSc
end
end
if bb.focus and not pSc and not qSc and not V.allyBuff(oSc.id)then
local ySc,zSc=bb.focusSpot(oSc)
if ySc then
return ySc,zSc
end
end
if O.fishiFollow and not pSc and not qSc then
local ASc,BSc,CSc,DSc,ESc=pcall(bb.drownBoss)
if ASc and BSc and not CSc and ESc and ESc[oSc.id]then
local FSc,GSc,HSc=pcall(bb.drownSpot,oSc,BSc)
if FSc and GSc then
return GSc,HSc
end
end
end
if not pSc and not qSc and not(bb.depth and bb.depth.leak)then
local ISc,JSc,KSc=pcall(bb.controlSpot,oSc)
if ISc and JSc then
return JSc,KSc
end
local LSc,MSc,NSc=pcall(bb.holdSpot,oSc)
if LSc and MSc then
return MSc,NSc
end
end
local OSc=bb.depth and bb.depth.leak
if bb.layout and bb.layout[oSc.id]and not pSc and not qSc then
local PSc=false
for QSc,RSc in ipairs(bb.mine or{})do
local SSc=RSc._stats:FindFirstChild(cue[2495])
if SSc and SSc.Value==oSc.uuid then
PSc=true
break
end
end
if not PSc then
for TSc,USc in ipairs(bb.layout[oSc.id])do
local VSc=bb.valid(USc,oSc.data)
if VSc and bb.sandLine()>0 and bb.cover(VSc,V.range(oSc.u,V.rows(oSc.id).max)*((bb.info and tonumber(bb.info.rangeScale))or 1))<=0 then
VSc=nil
end
if VSc and OSc then
local WSc,XSc,YSc=false,U.flat(VSc),V.range(oSc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local ZSc=bb.depth and bb.depth.leakLane and tostring(bb.depth.leakLane)or nil
for _Sc,aTc in ipairs(bb.hurtSamples())do
if aTc.prog>=OSc+0.02 and(not ZSc or tostring(aTc.lane)==ZSc)and(U.flat(aTc.pos)-XSc).Magnitude<=YSc then
WSc=true
break
end
end
if not WSc then
VSc=nil
end
