if VSc then
bb.layoutUsed=bb.layoutUsed or{}
bb.layoutUsed[oSc.id]=VSc
return VSc,bb.cover(VSc,V.range(oSc.u,math.min(3,V.rows(oSc.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1))
end
end
end
