local bTc=oSc.data
local cTc=bb.depth
local dTc,eTc=bb.hurtSamples(),bb.sandLine()
local fTc
if qSc then
fTc=1
for gTc,hTc in ipairs(bb.mine or{})do
local iTc=hTc._stats
if not V.isFarm(iTc.id.Value)and not(iTc:FindFirstChild(cue[2495])and iTc.uuid.Value==oSc.uuid)then
local jTc,kTc=U.flat(hTc:GetPivot().Position),iTc.range.Value
for lTc,mTc in ipairs(dTc)do
