local nTc=(bb.info and tonumber(bb.info.rangeScale))or 1
local oTc=V.range(oSc.u,(cTc and cTc.leak)and 0 or math.min(3,V.rows(oSc.id).max))*nTc
local pTc=(bb.kind==cue[2139]or bb.style==cue[3827]or bb.style==cue[3828])and not pSc and not(cTc and cTc.leak)and not V.isFarm(oSc.id)and V.range(oSc.u,V.rows(oSc.id).max)*nTc or nil
local qTc=V.allyBuff(oSc.id)
