local cUc=bb.infinite and bb.trainee and not qSc and oSc.uuid~=bb.trainee and not V.isFarm(oSc.id)and not qTc and not pSc and not(cTc and cTc.leak)and(bb.pressure or 0)<O.dangerReach and ib.ZONE or nil
local dUc=cUc and V.range(oSc.u,V.rows(oSc.id).max)or nil
