end
end
KUc=VUc/iUc*100+bb.cover(JUc,oTc,true)*0.05
else
local ZUc=bb.cover(JUc,oTc,true,cTc)
if pTc then
ZUc=bb.cover(JUc,pTc)+ZUc*0.25
end
KUc=ZUc+(GUc and 0 or(1-bb.progressAt(JUc))*0.5)
local _Uc=0
for aVc,bVc in ipairs(gUc)do
local cVc=bVc.b.types[fUc]
if cVc and(U.flat(bVc.pos)-U.flat(JUc)).Magnitude<=bVc.range then
_Uc=math.max(_Uc,math.min(cVc,_Uc+cVc*bVc.b.uptime))
end
end
KUc=KUc*(1+_Uc)
end
if qUc and(U.flat(qUc)-U.flat(JUc)).Magnitude<=rUc then
KUc=KUc+1e6
end
if sUc and(U.flat(sUc)-U.flat(JUc)).Magnitude<=tUc then
KUc=KUc+1e6
end
if uUc then
table.insert(uUc,{p=JUc,sc=KUc})
end
if not DUc or KUc>DUc then
CUc,DUc,EUc=JUc,KUc,bb.cover(JUc,oTc)
end
end
end
if qTc and#hUc>0 and CUc then
local dVc=false
for eVc,fVc in ipairs(hUc)do
if(U.flat(fVc.pos)-U.flat(CUc)).Magnitude<=oTc then
dVc=true
break
end
end
if not dVc then
return nil,0
end
end
if uUc and#uUc>0 then
table.sort(uUc,function(gVc,hVc)
return gVc.sc>hVc.sc
end)
for iVc=1,math.min(15,#uUc)do
local jVc,kVc=uUc[iVc].p,0
for lVc=0,7 do
local mVc=lVc*math.pi/4
if bb.valid(jVc+Vector3 .new(math.cos(mVc),0,math.sin(mVc))*5,bTc)then
kVc=kVc+1
end
if kVc>=2 then
break
end
end
if kVc>=2 then
return jVc,bb.cover(jVc,oTc)
end
end
end
return CUc,EUc or 0
end
function bb.lookAt(nVc)
local oVc,pVc=math.huge,nil
for qVc,rVc in ipairs(bb.samples)do
local sVc=(U.flat(rVc.pos)-U.flat(nVc)).Magnitude
if sVc<oVc then
oVc,pVc=sVc,rVc.pos
end
end
local tVc=pVc and U.flat(pVc-nVc)or Vector3 .new(0,0,-1)
return tVc.Magnitude>0.01 and tVc.Unit or Vector3 .new(0,0,-1)
end
