return true
end
if zVc>=(uVc.data.cost or 0)and bb.random then
bb.placeFail=bb.placeFail or{}
bb.placeFail[uVc.uuid]=(bb.placeFail[uVc.uuid]or 0)+1
if bb.placeFail[uVc.uuid]>=2 then
bb.noSpot[uVc.uuid]=3
F.log(1,cue[4232],string.format(cue[4417],V.name(uVc.id),bb.fieldCount(),bb.FIELD_MAX))
