if BVc and zVc>=(uVc.data.cost or 0)and not bb.random then
local DVc=bb.spotKey(xVc)
bb.refused[DVc]=true
bb.refusals=(bb.refusals or 0)+1
bb.unitRefusals[uVc.uuid]=(bb.unitRefusals[uVc.uuid]or 0)+1
if not bb.crowded()then
local EVc=bb.mapKey()
P.blocked[EVc]=P.blocked[EVc]or{}
if not bb.refusedRun[DVc]then
P.blocked[EVc][DVc]=(tonumber(P.blocked[EVc][DVc])or 0)+1
bb.refusedRun[DVc]=true
P.blockedAt[EVc]=P.blockedAt[EVc]or{}
P.blockedAt[EVc][DVc]=os.time()
end
if bb.unitRefusals[uVc.uuid]>=3 then
local FVc=math.max(1,bb.count(uVc.uuid))
if P.caps[uVc.uuid]~=FVc or not V.learnedCap(uVc.uuid)then
P.caps[uVc.uuid],P.capsAt[uVc.uuid]=FVc,os.time()
F.log(1,cue[4232],string.format(cue[4418],V.name(uVc.id),FVc))
end
end
elseif bb.unitRefusals[uVc.uuid]>=3 and(bb.noSpot[uVc.uuid]or 0)<3 then
