function bb.learn()
local Vcd=bb.calRun and bb.calRun.potBy
if type(Vcd)~=cue[2118]then
return
end
pcall(bb.sampleHelpers,true)
local Wcd={}
for Xcd,Ycd in pairs(bb.ownDealt or{})do
if not V.isFarm(Ycd.id)then
Wcd[Ycd.id]=(Wcd[Ycd.id]or 0)+(tonumber(Ycd.v)or 0)
end
end
for Zcd,_cd in pairs(bb.helperDealt or{})do
if _cd.owner and V.SUMMONER[_cd.owner]and not V.droneHelper(_cd)then
Wcd[_cd.owner]=(Wcd[_cd.owner]or 0)+(tonumber(_cd.v)or 0)
end
end
local bdd=type(bb.calRun.potExp)==cue[2118]and bb.calRun.potExp or{}
local cdd,ddd=0,0
local edd={}
for fdd,gdd in pairs(Vcd)do
if gdd>0 then
cdd,ddd=cdd+(Wcd[fdd]or 0),ddd+gdd
local hdd=tonumber(bdd[fdd])or gdd
if hdd>0 then
table.insert(edd,{id=fdd,r=(Wcd[fdd]or 0)/hdd,w=hdd})
end
end
end
if cdd<=0 or ddd<=0 then
return
end
table.sort(edd,function(idd,jdd)
return idd.r<jdd.r
end)
local function kdd(ldd)
local mdd,ndd=0,0
for odd,pdd in ipairs(edd)do
if pdd.id~=ldd then
mdd=mdd+pdd.w
end
end
if mdd<=0 then
return nil
end
for qdd,rdd in ipairs(edd)do
if rdd.id~=ldd then
ndd=ndd+rdd.w
if ndd>=mdd/2 then
return rdd.r
end
end
end
end
bb.lastEff={}
for sdd,tdd in pairs(Vcd)do
local udd=kdd(sdd)
if tdd>0 and tdd/ddd>0.02 and udd and udd>0 then
local vdd=P.learn[sdd]or{eff=1,n=0,v=6}
V.learnUp(sdd,vdd)
local wdd=math.max(0.02,0.25*math.sqrt(30/(30+vdd.n)))
local xdd=U.clamp(((Wcd[sdd]or 0)/tdd)/udd,0.2,6)
bb.lastEff[sdd]=math.floor(xdd*1000+0.5)/1000
vdd.eff=vdd.eff+(xdd-vdd.eff)*wdd
vdd.n=vdd.n+1
P.learn[sdd]=vdd
end
end
local ydd=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if ydd and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==cue[2118]and P.mapLearn or{}
local zdd=type(P.mapLearn[ydd])==cue[2118]and P.mapLearn[ydd]or{}
for Add,Bdd in pairs(bb.lastEff)do
local Cdd=type(zdd[Add])==cue[2118]and zdd[Add]or{eff=Bdd,n=0,v=6}
if(tonumber(Cdd.v)or 0)<4 then
Cdd.eff,Cdd.v=(tonumber(Cdd.eff)or Bdd)*V.secRescale(Add),4
end
if(tonumber(Cdd.v)or 0)<5 then
Cdd.eff,Cdd.v=(tonumber(Cdd.eff)or Bdd)*(V.sumRescale(Add)or 1),5
end
if(tonumber(Cdd.v)or 0)<6 then
Cdd.eff,Cdd.v=(tonumber(Cdd.eff)or Bdd)*(1-(V.SUMMONER[Add]and V.SUMMONER[Add].droneShare or 0)),6
end
local Ddd=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(Cdd.n)or 0))))
Cdd.eff=(tonumber(Cdd.n)or 0)==0 and Bdd or((tonumber(Cdd.eff)or Bdd)+(Bdd-(tonumber(Cdd.eff)or Bdd))*Ddd)
Cdd.n=(tonumber(Cdd.n)or 0)+1
zdd[Add]=Cdd
end
zdd._at=os.time()
P.mapLearn[ydd]=zdd
if U.count(P.mapLearn)>80 then
local Edd,Fdd
for Gdd,Hdd in pairs(P.mapLearn)do
if not Fdd or(tonumber(Hdd._at)or 0)<Fdd then
Edd,Fdd=Gdd,tonumber(Hdd._at)or 0
end
end
P.mapLearn[Edd]=nil
end
end
end
