end
end
local Vfd,Wfd=pcall(gb.wave,bb.info,math.max(1,bb.wave()),true)
local Xfd=V.attackInfo(Hfd.atk,Hfd.range)
return eb.shieldWork(Xfd.n,tonumber(Hfd.cd)or 2,Lfd,Ifd,Vfd and#Wfd or 1,bb.info.waveSec,Kfd*(bb.info.eff or 1),Jfd,Xfd.hits)
