function bb.baseVerdict(tjd,ujd)
local vjd=(ujd.t or 0)-(tjd.t or 0)
if vjd<bb.BASE_WIN-1 then
return false
end
local wjd=((tonumber(tjd.base)or 0)-(tonumber(ujd.base)or 0))/vjd
if wjd<=0 or(tonumber(ujd.base)or 0)<=0 then
return false
end
local xjd=ujd.base/wjd
local yjd,zjd=0,0
local Ajd,Bjd=tjd.foes or{},ujd.foes or{}
for Cjd,Djd in pairs(Bjd)do
if Djd.prog>=bb.BASE_END then
yjd=yjd+Djd.hp
local Ejd=Ajd[Cjd]
if Ejd then
zjd=zjd+math.max(0,Ejd.hp-Djd.hp)
end
end
end
for Fjd,Gjd in pairs(Ajd)do
if Gjd.prog>=bb.BASE_END and not Bjd[Fjd]then
zjd=zjd+Gjd.hp
end
end
if yjd<=0 then
return false
end
local Hjd=zjd/vjd
local Ijd=Hjd>0 and yjd/Hjd or math.huge
local Jjd={baseTime=xjd,loss=wjd,atEnd=yjd,rate=Hjd,killTime=Ijd}
return xjd<bb.BASE_SOON and Ijd>xjd*bb.BASE_MARGIN,Jjd
end
