if not bb.info or bb.info.noCC then
return
end
local Vnd=U.now()
local Wnd=bb.hw
if not Wnd then
Wnd={recs=setmetatable({},{__mode=cue[2504]}),list={},worked={},last=Vnd,cache={}}
bb.hw=Wnd
end
local Xnd=math.min(2,math.max(0,Vnd-Wnd.last))
Wnd.last=Vnd
local Ynd,Znd={},{}
for _nd,aod in ipairs(bb.mine or{})do
local bod=aod:FindFirstChild(cue[2182])
local cod=bod and bod:FindFirstChild(cue[2496])and bod.id.Value
if cod and bod:FindFirstChild(cue[2371])then
local dod=bod:FindFirstChild(cue[2225])
if V.GALE[cod]and dod and tostring(dod.Value):match(cue[4513])then
table.insert(Znd,{pos=U.flat(aod:GetPivot().Position),r=tonumber(bod.range.Value)or 0})
end
local eod=bod:FindFirstChild(cue[4425])and bod.target.Value
if typeof(eod)==cue[3677]and not eod:IsA(cue[4735])then
eod=eod:FindFirstAncestorOfClass(cue[4735])
end
local fod=bod:FindFirstChild(cue[2223])and bod.primary_attack.Value
if typeof(eod)==cue[3677]and eod.Parent and fod then
local god=tostring(fod)..cue[2254]..tostring(bod.range.Value)
local hod=Wnd.cache[god]
if hod==nil then
local iod,jod=pcall(V.attackInfo,fod,bod.range.Value)
hod=(iod and type(jod)==cue[2118]and jod.holdFam)and jod or false
Wnd.cache[god]=hod
end
local kod=eod:FindFirstChild(cue[3380])
if hod and kod then
local lod=bod:FindFirstChild(cue[2557])and tonumber(bod.attack_cooldown.Value)or 0
table.insert(Ynd,{tg=eod,tp=U.flat(kod.Position),at=U.flat(aod:GetPivot().Position),r=tonumber(bod.range.Value)or 0,fam=hod.holdFam,air=hod.ccAir,need=2*(lod>0 and lod or 2),full=hod.full,blast=math.min(12,math.max(0,((tonumber(hod.n)or 1)-1)*5))})
end
end
end
end
for nod,ood in ipairs(bb.enemies or{})do
local pod=ood.m
local qod=pod and Wnd.recs[pod]
if pod and not qod and#Wnd.list<bb.HOLD_MAX then
qod={uid=ood.uid,boss=ood.boss,held={},t={},need={},reached={}}
Wnd.recs[pod]=qod
table.insert(Wnd.list,qod)
end
if qod then
local rod=pod:FindFirstChild(cue[2508])
if rod then
for sod,tod in pairs(bb.HOLD_SLOTS)do
if not qod.held[sod]then
for uod,vod in ipairs(tod)do
local wod=rod:FindFirstChild(vod)
if wod and tonumber(wod.Value)and wod.Value~=0 then
qod.held[sod]=true
Wnd.worked[sod]=true
break
end
end
end
end
end
local xod=pod:FindFirstChild(cue[2182])
local yod=xod and xod:FindFirstChild(cue[4736])and(tonumber(xod.Fire.Value)or 0)>0
local zod=xod and xod:FindFirstChild(cue[4737])and(tonumber(xod.invincible.Value)or 0)>0
if Xnd>0 and not yod and not zod and(ood.sh or 0)<=0 then
local Aod=U.flat(ood.pos)
local Bod={}
for Cod,Dod in ipairs(Ynd)do
if not(ood.fly and not Dod.air)then
local Eod=Dod.tg==pod or(Dod.full and(Aod-Dod.at).Magnitude<=Dod.r)or(Dod.blast>0 and(Aod-Dod.tp).Magnitude<=Dod.blast)
if Eod then
for Fod in pairs(Dod.fam)do
Bod[Fod]=math.max(Bod[Fod]or 0,Dod.need)
end
end
end
end
if not ood.fly then
for God,Hod in ipairs(Znd)do
if(Aod-Hod.pos).Magnitude<=Hod.r then
Bod.slow=math.max(Bod.slow or 0,3)
end
end
end
for Iod,Jod in pairs(Bod)do
qod.t[Iod]=(qod.t[Iod]or 0)+Xnd
qod.need[Iod]=math.max(qod.need[Iod]or 0,Jod)
if qod.t[Iod]>=qod.need[Iod]then
qod.reached[Iod]=true
end
end
end
end
end
end
function bb.holdFold()
local Kod=bb.hw
bb.hw=nil
if type(Kod)~=cue[2118]or#Kod.list==0 then
return
end
P.holdSeen=type(P.holdSeen)==cue[2118]and P.holdSeen or{}
local Lod={}
for Mod,Nod in ipairs(Kod.list)do
if Nod.uid then
local Ood=type(P.holdSeen[Nod.uid])==cue[2118]and P.holdSeen[Nod.uid]or{}
for Pod in pairs(bb.HOLD_SLOTS)do
local Qod=Nod.held[Pod]==true
if Qod or(Nod.reached[Pod]and Kod.worked[Pod])then
local Rod=type(Ood[Pod])==cue[2118]and Ood[Pod]or{s=0,h=0}
local Sod,Tod=tonumber(Rod.h)or 0,tonumber(Rod.s)or 0
Rod.s,Rod.h,Rod.at=Tod+1,Sod+(Qod and 1 or 0),os.time()
Ood[Pod]=Rod
if Qod and Sod==0 and Nod.boss then
Lod[Nod.uid..cue[2254]..Pod]={uid=Nod.uid,fam=Pod,took=true}
end
if not Qod and Rod.h==0 and Tod<gb.HOLD_IMMUNE_N and Rod.s>=gb.HOLD_IMMUNE_N then
Lod[Nod.uid..cue[2254]..Pod]={uid=Nod.uid,fam=Pod,n=Rod.s}
end
end
end
if next(Ood)then
P.holdSeen[Nod.uid]=Ood
end
end
end
for Uod,Vod in pairs(Lod)do
local Wod=(pcall(V.name,Vod.uid)and V.name(Vod.uid))or Vod.uid
if Vod.took then
F.log(1,cue[2492],string.format(cue[4738],tostring(Wod),bb.HOLD_WORD[Vod.fam]or Vod.fam))
else
F.log(1,cue[2492],string.format(cue[4739],tostring(Wod),bb.HOLD_WORD[Vod.fam]or Vod.fam,Vod.n))
end
end
pcall(F.saveSoon)
end
function bb.drownTick()
local Xod,Yod,Zod,_od,apd=pcall(bb.drownBoss)
if not(Xod and Yod)then
bb.drownTarget=nil
return
end
bb.drownTarget=Zod and Yod or nil
if Zod then
return
end
local bpd=bb.drownState
if not bpd or bpd.m~=Yod.m then
bpd={m=Yod.m,moves=0,at=0}
bb.drownState=bpd
end
if bpd.moves>=bb.DROWN_MOVES or U.now()-bpd.at<bb.DROWN_EVERY then
return
end
local cpd=1
pcall(function()
cpd=N.USC.calculate_spawn_cost_multiplier(N.session())
end)
for dpd,epd in pairs(apd)do
local fpd={}
for gpd,hpd in ipairs(_od)do
if hpd._stats.id.Value==dpd then
table.insert(fpd,hpd)
end
end
if#fpd>=V.cap(epd.u)then
local ipd=(tonumber(epd.data and epd.data.cost)or 0)*cpd
local jpd,kpd
for lpd,mpd in ipairs(fpd)do
local npd=mpd._stats
local opd,ppd=U.flat(mpd:GetPivot().Position),npd.range.Value
local qpd=false
for rpd,spd in ipairs(bb.samples)do
if spd.prog>=Yod.prog and(U.flat(spd.pos)-opd).Magnitude<=ppd then
qpd=true
break
end
end
local tpd=npd:FindFirstChild(cue[4234])and tonumber(npd.total_spent.Value)or 0
if not qpd and tpd<=2.5*ipd and(not kpd or tpd<kpd)then
jpd,kpd=mpd,tpd
end
end
if jpd and bb.money()+gb.SELL_BACK*kpd>=ipd then
bpd.at,bpd.moves=U.now(),bpd.moves+1
local upd,vpd=F.request(cue[2301],cue[2499],jpd)
if vpd==true then
F.log(1,cue[4232],string.format(cue[4740],V.name(dpd),U.fmt(kpd),U.fmt(Yod.hp)))
task.wait(0.5)
local wpd,xpd=pcall(bb.place,epd,cue[4741])
if not wpd then
F.log(1,cue[2505],cue[4742]..tostring(xpd))
end
end
return
end
end
end
end
bb.cashTried=setmetatable({},{__mode=cue[2504]})
function bb.lastWaveCash()
if not(bb.total and bb.wave()>=bb.total and not bb.infinite)or bb.spellBusy then
return
end
local ypd=N.session()
local zpd
for Apd,Bpd in pairs((ypd and ypd.ingame_spells)or{})do
if Bpd==cue[4683]then
zpd=Apd
end
end
local Cpd,Dpd
for Epd,Fpd in ipairs(bb.mine)do
local Gpd=Fpd._stats
local Hpd=N.Units[Gpd.id.Value]
if V.isFarm(Gpd.id.Value)and not(Hpd and Hpd.unsellable)and(bb.cashTried[Fpd]or 0)<2 then
local Ipd=Gpd:FindFirstChild(cue[4234])and tonumber(Gpd.total_spent.Value)or 0
if not Dpd or Ipd>Dpd then
Cpd,Dpd=Fpd,Ipd
end
end
end
if not Cpd then
return
end
bb.cashTried[Cpd]=(bb.cashTried[Cpd]or 0)+1
local Jpd=V.name(Cpd._stats.id.Value)
if zpd then
bb.spellBusy=true
local Kpd=F.request(cue[4690],cue[4691],zpd,Cpd)
bb.spellBusy=false
if Kpd then
F.log(1,cue[4676],string.format(cue[4743],Jpd,U.fmt(Dpd)))
end
else
local Lpd,Mpd=F.request(cue[2301],cue[2499],Cpd)
if Mpd==true then
F.log(1,cue[4232],string.format(cue[4744],Jpd,U.fmt(Dpd)))
elseif bb.cashTried[Cpd]>=2 then
F.log(1,cue[4232],string.format(cue[4745],Jpd))
end
end
