bb.mergeIds={}
function bb.mergeScan()
bb.mergePlan,bb.mergeIds=nil,{}
if not bb.random then
return
end
local Npd=N.session()
local Opd=false
bb.cloneCard=false
for Ppd,Qpd in pairs((Npd and Npd.ingame_spells)or{})do
if Qpd==cue[4681]then
Opd=true
elseif Qpd==cue[4746]then
bb.cloneCard=true
end
end
local Rpd={}
local Spd=P.fh.noMerge or{}
for Tpd,Upd in ipairs(bb.mine or{})do
local Vpd=Upd._stats
local Wpd=Vpd.id.Value
if not V.isFarm(Wpd)and not V.allyBuff(Wpd)and not V.idol(Wpd)and Vpd:FindFirstChild(cue[2507])and(Spd[Wpd]or 0)<2 then
local Xpd,Ypd=pcall(bb.liveDps,Upd,Wpd)
Rpd[Wpd]=Rpd[Wpd]or{}
table.insert(Rpd[Wpd],{m=Upd,lvl=Vpd.upgrade.Value,max=Vpd.max_upgrade.Value,dps=Xpd and Ypd or 0})
end
end
local Zpd={}
for _pd,aqd in ipairs(bb.team or{})do
if aqd.hand then
Zpd[aqd.id]=true
end
end
local bqd={}
for cqd,dqd in pairs(Rpd)do
table.sort(dqd,function(eqd,fqd)
if eqd.dps~=fqd.dps then
return eqd.dps>fqd.dps
end
return eqd.lvl>fqd.lvl
end)
table.insert(bqd,{id=cqd,dps=dqd[1].dps*bb.airBoost(dqd[1].m)*bb.reach(dqd[1].m)})
end
table.sort(bqd,function(gqd,hqd)
return gqd.dps>hqd.dps
end)
for iqd=1,math.min(3,#bqd)do
bb.mergeIds[bqd[iqd].id]=true
end
local jqd
for kqd,lqd in pairs(Rpd)do
local mqd=table.clone(lqd)
table.sort(mqd,function(nqd,oqd)
if nqd.lvl~=oqd.lvl then
return nqd.lvl<oqd.lvl
end
return nqd.dps<oqd.dps
end)
for pqd,qqd in ipairs(mqd)do
if qqd.m==bb.freshM and pqd>1 then
table.remove(mqd,pqd)
table.insert(mqd,1,qqd)
break
end
end
local rqd,sqd,tqd,uqd
for vqd,wqd in ipairs(mqd)do
local xqd,yqd=U.flat(wqd.m:GetPivot().Position),wqd.m._stats.range.Value
local zqd,Aqd,Bqd=0,0,nil
for Cqd,Dqd in ipairs(lqd)do
if Dqd~=wqd and(U.flat(Dqd.m:GetPivot().Position)-xqd).Magnitude<=yqd then
zqd,Aqd=zqd+Dqd.dps,Aqd+1
if not Bqd or Dqd.dps>Bqd.dps then
Bqd=Dqd
end
end
end
if Aqd>0 then
rqd,sqd,tqd,uqd=wqd,zqd,Aqd,Bqd
break
end
end
uqd=uqd or lqd[1]
local Eqd=uqd.dps*bb.airBoost(uqd.m)*bb.reach(uqd.m)*(kqd==bb.planId and 2 or 1)
if(bb.mergeIds[kqd]or kqd==bb.planId)and(rqd or Zpd[kqd])and(not jqd or Eqd>jqd.score)then
jqd={id=kqd,top=uqd,fresh=rqd,near=sqd or 0,n=tqd or 0,coming=Zpd[kqd],score=Eqd}
end
end
bb.planId,bb.freshM=jqd and jqd.id,jqd and jqd.fresh and jqd.fresh.m
bb.mergeHeldAt=(Opd and jqd and jqd.fresh)and(bb.mergeHeldAt or bb.wave())or nil
if not jqd then
return F.status(cue[4659],cue[4747])
end
local Fqd,Gqd=bb.wave(),(bb.total or 30)-bb.wave()
local Hqd=(bb.pressure or 0)>=math.min(O.dangerReach,((bb.depth and bb.depth.units>0 and bb.depth.covEnd)or 1)*0.9)
local Iqd=jqd.fresh
local Jqd=not Hqd and Gqd>3
jqd.waits=Iqd and Iqd.lvl<=jqd.top.lvl and jqd.top.lvl<jqd.top.max and Jqd or false
local Kqd=(not Iqd or Iqd.lvl>=jqd.top.lvl)and jqd.coming and Jqd
local Lqd=bb.cloneCard and jqd.top.lvl>=jqd.top.max and Jqd
local Mqd=Iqd and Iqd.lvl>jqd.top.lvl and jqd.near<0.3*Iqd.dps
jqd.ready=Opd and Iqd~=nil and not Mqd and(not(jqd.waits or Kqd or Lqd)or Fqd-(bb.mergeHeldAt or Fqd)>=5)
bb.holdNoCardAt=(jqd.waits and not Opd)and(bb.holdNoCardAt or Fqd)or nil
jqd.hold=jqd.waits and(Opd or Fqd-(bb.holdNoCardAt or Fqd)<4)
bb.mergePlan=jqd
F.status(cue[4659],Iqd and string.format(cue[4748],V.name(jqd.id),jqd.n,jqd.n==1 and cue[4749]or cue[4750],Iqd.lvl,jqd.ready and cue[4751]or(Opd and cue[4752]or cue[4753]))or string.format(cue[4754],V.name(jqd.id)))
end
function bb.mergeHold(Nqd)
local Oqd=bb.mergePlan
return Oqd and Oqd.hold and Oqd.fresh and Oqd.fresh.m==Nqd or false
end
function bb.mergeBoost(Pqd)
local Qqd=bb.mergePlan
if not(Qqd and Qqd.top.m==Pqd and(Qqd.fresh or Qqd.coming))then
return 1
end
return bb.mergeHeldAt and 2 or 1.3
end
function bb.mergeSpot(Rqd)
if not(bb.random and bb.mergeIds[Rqd.id])then
return nil
end
local Sqd,Tqd
for Uqd,Vqd in ipairs(bb.mine or{})do
if Vqd._stats.id.Value==Rqd.id then
local Wqd,Xqd=pcall(bb.liveDps,Vqd,Rqd.id)
Xqd=Wqd and Xqd or 0
if not Tqd or Xqd>Tqd then
Sqd,Tqd=Vqd,Xqd
