function bb.mergeMeasure(Yqd)
local Zqd=bb.mergeBefore
if not Zqd then
return
end
task.delay(2,function()
if not(Yqd and Yqd.Parent)then
return
end
local _qd,ard=pcall(bb.liveDps,Yqd,Yqd._stats.id.Value)
if not _qd then
return
end
local brd=Zqd.own+1.5*Zqd.near
local crd=P.fh.merge or{n=0,ratio=0}
if brd>0 then
crd.n,crd.ratio=crd.n+1,crd.ratio+ard/brd
end
P.fh.merge=crd
local drd=Yqd._stats.id.Value
P.fh.noMerge=P.fh.noMerge or{}
local erd,frd=ard-Zqd.own,1.5*Zqd.near
if frd>0 and erd<0.1*frd then
P.fh.noMerge[drd]=(P.fh.noMerge[drd]or 0)+1
elseif frd>0 and erd>=0.5*frd then
P.fh.noMerge[drd]=nil
end
F.log(1,cue[4676],string.format(cue[4755],V.name(Yqd._stats.id.Value),U.fmt(Zqd.own),U.fmt(ard),Zqd.lvl,U.fmt(Zqd.near),U.fmt(brd),Zqd.top))
end)
end
function bb.farmMergeOk()
local grd=P.fh.farmMerge
if not(grd and grd.n>0)then
return true
end
return grd.ratio/grd.n>=0.8
end
function bb.farmMergePair()
local hrd={}
for ird,jrd in ipairs(bb.mine or{})do
local krd=jrd._stats.id.Value
if V.isFarm(krd)and jrd._stats:FindFirstChild(cue[2227])then
hrd[krd]=hrd[krd]or{}
table.insert(hrd[krd],jrd)
end
end
for lrd,mrd in pairs(hrd)do
if#mrd>=2 then
table.sort(mrd,function(nrd,ord)
return nrd._stats.upgrade.Value<ord._stats.upgrade.Value
end)
for prd,qrd in ipairs(mrd)do
local rrd,srd=U.flat(qrd:GetPivot().Position),qrd._stats.range.Value
local trd,urd=0,0
for vrd,wrd in ipairs(mrd)do
if wrd~=qrd and(U.flat(wrd:GetPivot().Position)-rrd).Magnitude<=srd then
trd,urd=trd+(tonumber(wrd._stats.farm_amount.Value)or 0),urd+1
end
end
if urd>0 then
return qrd,trd,urd
end
end
end
end
end
function bb.farmMergeSpot(xrd)
if not(bb.random and bb.farmMergeOk())then
return nil
end
for yrd,zrd in ipairs(bb.mine or{})do
if zrd._stats.id.Value==xrd.id then
return zrd:GetPivot().Position,tonumber(zrd._stats.range.Value)or 0
end
end
end
function bb.farmMergeMeasure(Ard)
