function bb.idolMeasure()
local Ird
for Jrd,Krd in ipairs(bb.mine)do
local Lrd=Krd._stats.id.Value
local Mrd=Krd._stats:FindFirstChild(cue[2556])
if not V.isFarm(Lrd)and not V.idol(Lrd)and Mrd and Mrd.Value>0 then
