local Rrd=Nrd:FindFirstChild(cue[4507])and tonumber(Nrd.buff_damage_multiplier.Value)or 0
return Nrd.damage.Value*(1+Rrd),Prd and tonumber(Qrd)or nil
end
local Srd,Trd=Ord()
