end
local Xrd=P.fh.idol or{n=0,dmg=0,cost=0}
Xrd.n,Xrd.dmg,Xrd.cost=Xrd.n+1,Xrd.dmg+(Vrd/Srd-1),Xrd.cost+(1-Wrd/Trd)
P.fh.idol=Xrd
