function bb.spells()
local Yrd=N.session()
local Zrd=Yrd and Yrd.ingame_spells
if type(Zrd)~=cue[2118]or bb.spellBusy then
return
end
local _rd=bb.money()
local asd=(bb.pressure or 0)>=math.min(O.dangerReach,((bb.depth and bb.depth.units>0 and bb.depth.covEnd)or 1)*0.9)
local bsd,csd,dsd
for esd,fsd in ipairs(bb.mine)do
local gsd=fsd._stats.id.Value
if not V.isFarm(gsd)and not V.allyBuff(gsd)and gsd~=cue[4212]then
local hsd,isd=pcall(bb.liveDps,fsd,gsd)
local jsd=hsd and isd and isd*bb.airBoost(fsd)*bb.reach(fsd)
if jsd and(not dsd or jsd>dsd)then
bsd,csd,dsd=fsd,isd,jsd
end
end
end
local ksd=bb.mergePlan
local lsd={}
for msd,nsd in pairs(Zrd)do
table.insert(lsd,{slot=msd,spell=nsd,rank=bb.SPELL_ORDER[nsd]or 9})
end
table.sort(lsd,function(osd,psd)
return osd.rank<psd.rank
end)
bb.spellWant=nil
bb.cloneNote=nil
for qsd,rsd in ipairs(lsd)do
local ssd,tsd=rsd.slot,rsd.spell
local usd,vsd
local wsd
for xsd,ysd in ipairs(bb.mine)do
if ysd._stats.id.Value==cue[4212]then
wsd=ysd
end
end
