function nb.K.key(s_d,t_d)
local u_d,v_d,w_d=nb.K,nb.Win,Enum.KeyCode
if u_d.cur and not(u_d.cur.obj and u_d.cur.obj.Parent and u_d.shown(u_d.cur.obj))then
u_d.setFocus(nil)
end
if u_d.cur and u_d.cur.listKey and u_d.cur.listKey(s_d)then
return true
end
if s_d==w_d.PageUp or s_d==w_d.PageDown then
local x_d={}
for y_d,z_d in pairs(v_d._tabs)do
table.insert(x_d,{name=y_d,y=z_d.btn.AbsolutePosition.Y,on=z_d.page.Visible})
end
table.sort(x_d,function(A_d,B_d)
return A_d.y<B_d.y
end)
local C_d=1
for D_d,E_d in ipairs(x_d)do
if E_d.on then
C_d=D_d
end
end
C_d=(C_d-1+(s_d==w_d.PageDown and 1 or-1))% #x_d+1
u_d.setFocus(nil)
v_d:SelectTab(x_d[C_d].name)
return true
end
if s_d==w_d.Tab or s_d==w_d.Down or s_d==w_d.Up then
local F_d=u_d.order()
if#F_d==0 then
return true
end
local G_d=s_d==w_d.Up or(s_d==w_d.Tab and t_d)
local H_d=table.find(F_d,u_d.cur)
if not H_d then
H_d=G_d and#F_d or 1
else
H_d=(H_d-1+(G_d and-1 or 1))% #F_d+1
end
u_d.setFocus(F_d[H_d])
return true
end
if not u_d.cur then
return false
end
if s_d==w_d.Return or s_d==w_d.KeypadEnter or s_d==w_d.Space then
if u_d.cur.activate then
u_d.cur.activate()
end
return true
end
if s_d==w_d.Left or s_d==w_d.Right then
if u_d.cur.adjust then
u_d.cur.adjust(s_d==w_d.Right and 1 or-1)
end
return true
end
if s_d==w_d.Escape then
u_d.setFocus(nil)
return true
end
return false
end
